B.aDr=s(["\u062b\u0645 \u0627\u0646\u0637\u0644\u0642 \u0631\u0624\u0648\u0633 \u0627\u0644\u0643\u064f\u0641\u0631 \u0648\u0623\u0630\u064a\u0627\u0644\u064f\u0647\u0645 \u0625\u0644\u0649 \u0623\u0628\u064a \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u064a\u0642\u0648\u0644\u0648\u0646 \u0644\u0647: \u0623\u062a\u0635\u062f\u0651\u0650\u0642\u064f \u0635\u0627\u062d\u0628\u064e\u0643\u061f \u064a\u0632\u0639\u0645\u064f \u0623\u0646\u0647 \u0623\u064f\u0633\u0631\u0650\u064a \u0628\u0647 \u0644\u064a\u0644\u064b\u0627 \u0625\u0644\u0649 \u0628\u064a\u062a\u0650 \u0627\u0644\u0645\u0642\u062f\u0633. \u0641\u0642\u0627\u0644\u064e: \u0623\u064e\u0648\u064e\u0642\u0627\u0644\u064e \u0630\u0644\u0643\u061f \u0642\u0627\u0644\u0648\u0627: \u0646\u0639\u0645. \u0642\u0627\u0644: \u0625\u0646 \u0643\u0627\u0646 \u0642\u062f \u0642\u0627\u0644\u060c \u0641\u0642\u062f \u0635\u064e\u062f\u064e\u0642\u060c \u0625\u0646\u0651\u064a \u0644\u0623\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064f\u0647 \u0641\u064a \u0623\u0628\u0639\u062f\u064e \u0645\u0646 \u0630\u0644\u0643\u060c \u0623\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064f\u0647 \u0641\u064a \u062e\u0628\u0631\u0650 \u0627\u0644\u0633\u0645\u0627\u0621\u0650.",u.gC,u.bW,"\u0623\u0645\u0651\u0627 \u0647\u0624\u0644\u0627\u0621\u0650 \u0627\u0644\u0645\u0639\u0627\u0646\u062f\u0648\u0646 \u0641\u0643\u0627\u0646\u062a \u0627\u0644\u0622\u064a\u0627\u062a\u0650 \u0643\u0627\u0634\u0641\u0629\u064b \u0644\u0643\u0630\u0628\u0647\u0645\u060c \u0641\u0627\u0636\u062d\u0629 \u0644\u0639\u0646\u0627\u062f\u0647\u0645\u060c \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0646\u0627 \u0639\u064e\u0644\u0649 \u0642\u064f\u0644\u0648\u0628\u0650\u0647\u0650\u0645 \u0623\u064e\u0643\u0650\u0646\u0651\u064e\u0629\u064b \u0623\u064e\u0646 \u064a\u064e\u0641\u0642\u064e\u0647\u0648\u0647\u064f \u0648\u064e\u0641\u064a \u0622\u0630\u0627\u0646\u0650\u0647\u0650\u0645 \u0648\u064e\u0642\u0631\u064b\u0627 \u0648\u064e\u0625\u0650\u0630\u0627 \u0630\u064e\u0643\u064e\u0631\u062a\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0642\u064f\u0631\u0622\u0646\u0650 \u0648\u064e\u062d\u062f\u064e\u0647\u064f \u0648\u064e\u0644\u0651\u064e\u0648\u0627 \u0639\u064e\u0644\u0649 \u0623\u064e\u062f\u0628\u0627\u0631\u0650\u0647\u0650\u0645 \u0646\u064f\u0641\u0648\u0631\u064b\u0627\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0625\u0633\u0631\u0627\u0621"],t.s)
