B.aLF=s(["\u0644\u0645 \u064a\u0643\u0646 \u0625\u064a\u0645\u0627\u0646\u064f \u0623\u0628\u064a \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0648\u0644\u064b\u0627 \u064a\u064f\u0631\u062f\u0651\u064e\u062f\u060c \u0628\u0644 \u0641\u062f\u0627\u0621\u064b \u064a\u064f\u0642\u062f\u0651\u064e\u0645\u061b \u0641\u0643\u0627\u0646 \u064a\u0634\u062a\u0631\u064a \u0631\u0642\u0627\u0628\u064e \u0627\u0644\u0645\u064f\u0639\u0630\u0628\u064a\u0646 \u0648\u064a\u0639\u062a\u0642\u0647\u0645 \u0644\u0648\u062c\u0647\u0650 \u0627\u0644\u0644\u0647\u060c \u0625\u064a\u0645\u0627\u0646\u064b\u0627 \u0645\u0646\u0647 \u0628\u0623\u0646\u0651 \u0646\u0635\u0631\u0629\u064e \u0627\u0644\u062f\u064a\u0646 \u0644\u064a\u0633\u062a \u0643\u0644\u0645\u0627\u062a\u064d \u062a\u064f\u0642\u0627\u0644\u060c \u0628\u0644 \u0623\u062b\u0645\u0627\u0646\u064b\u0627 \u062a\u064f\u062f\u0641\u0639.","\u0648\u0647\u0627 \u0647\u0648 \u0628\u0644\u0627\u0644 \u0628\u0646 \u0631\u0628\u0627\u062d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u064a\u062f\u0641\u0639 \u062b\u0645\u0646 \u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u062a\u064a \u0622\u0645\u0646 \u0628\u0647\u0627\u060c \u0641\u0641\u064a \u0644\u0647\u064a\u0628 \u062d\u0631\u0651\u0650 \u0645\u0643\u0629 \u0643\u0627\u0646 \u064a\u064f\u0639\u0630\u0628 \u0648\u0627\u0644\u0633\u064a\u0627\u0637 \u062a\u064f\u0645\u0632\u0642 \u062c\u0633\u062f\u0647\u060c \u0644\u0627 \u0644\u062c\u0631\u0645\u064d \u0627\u0642\u062a\u0631\u0641\u0647 \u0628\u0644 \u0644\u0623\u0646\u0647 \u0646\u0637\u0642 \u0628\u0643\u0644\u0645\u0629\u064d \u062f\u0648\u0651\u062a \u0641\u064a \u0622\u0630\u0627\u0646 \u0637\u0648\u0627\u063a\u064a\u062a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 .. \u0623\u062d\u062f\u064c \u0623\u062d\u062f \u060c \u0648\u062d\u0627\u0648\u0644 \u0623\u0645\u064a\u0629 \u0628\u0646 \u062e\u0644\u0641 -\u0644\u0639\u0646\u0647 \u0627\u0644\u0644\u0647- \u0643\u0633\u0631\u064e \u0639\u0642\u064a\u062f\u0629\u0650 \u0628\u0644\u0627\u0644\u060c \u0645\u062a\u0648\u0647\u0645\u064b\u0627 \u0623\u0646 \u0627\u0644\u0633\u0648\u0637\u064f \u064a\u0633\u062a\u0637\u064a\u0639\u064f \u0643\u0633\u0631 \u0625\u0631\u0627\u062f\u0629\u0650 \u0645\u0646 \u062a\u0645\u0633\u0651\u0643 \u0628\u0627\u0644\u062d\u0642\u061b \u0648\u0630\u0644\u0643 \u0645\u0646\u0637\u0642 \u0627\u0644\u062c\u0644\u0627\u062f\u064a\u0646 \u0648\u063a\u0628\u0627\u0621\u064f \u0627\u0644\u0637\u063a\u0627\u0629 \u0627\u0644\u0630\u064a\u0646 \u0644\u0645 \u064a\u062a\u0639\u0644\u0645\u0648\u0627 \u0627\u0644\u062f\u0631\u0633 \u0628\u0639\u062f.","\u0648\u0627\u0644\u0646\u0627\u0633 \u062a\u0631\u0649 \u0628\u0644\u0627\u0644 \u064a\u064f\u0639\u0630\u0628 \u0648\u062a\u0644\u062a\u0632\u0645 \u0627\u0644\u0635\u0645\u062a \u062a\u062d\u062a \u0648\u0637\u0623\u0629 \u0633\u0648\u0637 \u0623\u0645\u064a\u0629 -\u0644\u0639\u0646\u0647 \u0627\u0644\u0644\u0647- \u060c \u0644\u0643\u0646 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0644\u0645 \u064a\u062a\u062d\u0645\u0644 \u0631\u0624\u064a\u0629 \u0647\u0630\u0627\u060c \u0641\u0644\u0645\u0627 \u0645\u0631\u0651 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0645\u0634\u0647\u062f\u060c \u0642\u0627\u0644 \u0644\u0623\u0645\u064a\u0629: \u0623\u0644\u0627 \u062a\u062a\u0651\u0642\u064a \u0627\u0644\u0644\u0647 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0645\u0633\u0643\u064a\u0646\u061f \u060c \u0641\u0642\u0627\u0644 \u0623\u0645\u064a\u0629: \u0623\u0646\u062a \u0627\u0644\u0630\u064a \u0623\u0641\u0633\u062f\u062a\u0647 \u0641\u0623\u0646\u0642\u0630\u0647 \u0645\u0645\u0627 \u062a\u0631\u0649\u060c \u0641\u0623\u0634\u062a\u0631\u0627\u0647 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0628\u062e\u0645\u0633 \u0623\u0648\u0627\u0642\u064d \u0630\u0647\u0628\u064b\u0627\u060c \u0648\u062f\u0641\u0639 \u0627\u0644\u062b\u0645\u0646 \u062f\u0648\u0646 \u0645\u0633\u0627\u0648\u0645\u0629\u060c \u0648\u0642\u0627\u0644 \u0644\u0628\u0644\u0627\u0644: \u0623\u0646\u062a \u062d\u0631\u0651\u064c."],t.s)
