B.ax9=s(["\u062a\u0631\u0648\u0649 \u0623\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0627\u0644\u0633\u064a\u062f\u0629 \u0639\u0627\u0626\u0634\u0629 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627: \u0644\u0645\u0627 \u062b\u0642\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062c\u0627\u0621 \u0628\u0644\u0627\u0644 \u064a\u064f\u0624\u0630\u0650\u0646\u064f\u0647 \u0628\u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0641\u0642\u0627\u0644: \u0645\u064f\u0631\u064f\u0648\u0627 \u0623\u0628\u064e\u0627 \u0628\u064e\u0643\u0631\u064d \u0623\u0646 \u064a\u064f\u0635\u0644\u064a \u0628\u0627\u0644\u0646\u0627\u0633\u060c \u0641\u0642\u0644\u062a: \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0625\u0646 \u0623\u0628\u0627 \u0628\u0643\u0631\u064d \u0631\u062c\u0644 \u0623\u0633\u0650\u064a\u0641 \u0648\u0625\u0646\u0647 \u0645\u062a\u0649 \u0645\u0627 \u064a\u064e\u0642\u064f\u0645 \u0645\u0642\u0627\u0645\u0643 \u0644\u0627 \u064a\u064f\u0633\u0645\u0650\u0639 \u0627\u0644\u0646\u0627\u0633\u060c \u0641\u0644\u0648 \u0623\u0645\u0631\u062a \u0639\u0645\u0631\u060c \u0641\u0642\u0627\u0644: \u0645\u064f\u0631\u064f\u0648\u0627 \u0623\u0628\u064e\u0627 \u0628\u064e\u0643\u0631\u064d \u064a\u064f\u0635\u0644\u064a \u0628\u0627\u0644\u0646\u0627\u0633 \u0641\u0642\u064f\u0644\u062a\u064f \u0644\u062d\u0641\u0635\u0629: \u0642\u0648\u0644\u0650\u064a \u0644\u0647: \u0625\u0646 \u0623\u0628\u064e\u0627 \u0628\u064e\u0643\u0631\u064d \u0631\u062c\u0644 \u0623\u0633\u0650\u064a\u0641\u060c \u0648\u0625\u0646\u0647 \u0645\u062a\u0649 \u064a\u064e\u0642\u0645 \u0645\u0642\u0627\u0645\u0643 \u0644\u0627 \u064a\u064f\u0633\u0645\u0650\u0639 \u0627\u0644\u0646\u0627\u0633\u060c \u0641\u0644\u0648 \u0623\u0645\u064e\u0631\u062a \u0639\u0645\u0631\u060c \u0642\u0627\u0644: \u0625\u0646\u0651\u064e\u0643\u064f\u0646 \u0644\u0623\u0646\u062a\u064f\u0646\u0651\u064e \u0635\u064e\u0648\u064e\u0627\u062d\u0650\u0628 \u064a\u064f\u0648\u0633\u0641\u060c \u0645\u064f\u0631\u064f\u0648\u0627 \u0623\u0628\u064e\u0627 \u0628\u064e\u0643\u0631\u064d \u0623\u0646 \u064a\u064f\u0635\u0644\u064a \u0628\u0627\u0644\u0646\u0627\u0633 \u0641\u0644\u0645\u0627 \u062f\u064e\u062e\u0644 \u0641\u064a \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u062c\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u064a \u0646\u0641\u0633\u0650\u0647\u0650 \u062e\u0650\u0641\u0629\u060c \u0641\u0642\u0627\u0645 \u064a\u064f\u0647\u0627\u062f\u064e\u0649 \u0628\u064a\u0646 \u0631\u062c\u0644\u064a\u0646\u060c \u0648\u0631\u0650\u062c\u0644\u0627\u0647 \u064a\u062e\u064f\u0637\u0627\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u062d\u062a\u0649 \u062f\u062e\u0644 \u0627\u0644\u0645\u0633\u062c\u062f\u060c \u0641\u0644\u0645\u0627 \u0633\u064e\u0645\u0650\u0639 \u0623\u0628\u0648 \u0628\u0643\u0631 \u062d\u0650\u0633\u0647\u064f\u060c \u0630\u0647\u0628 \u0623\u0628\u0648 \u0628\u0643\u0631 \u064a\u062a\u0623\u062e\u0631\u060c \u0641\u0623\u0648\u0652\u0645\u064e\u0623 \u0625\u0644\u064a\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0641\u062c\u0627\u0621 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062d\u062a\u0649 \u062c\u0644\u0633 \u0639\u0646 \u064a\u0633\u0627\u0631 \u0623\u0628\u0650\u064a \u0628\u0643\u0631\u064d\u060c \u0641\u0643\u0627\u0646 \u0623\u0628\u0648 \u0628\u0643\u0631 \u064a\u064f\u0635\u064e\u0644\u064a \u0642\u0627\u0626\u0650\u0645\u064b\u0627\u060c \u0648\u0643\u0627\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u064f\u0635\u064e\u0644\u064a \u0642\u0627\u0639\u0650\u062f\u064b\u0627\u060c \u064a\u064e\u0642\u062a\u062f\u064a \u0623\u0628\u0648 \u0628\u0643\u0631 \u0628\u0635\u0644\u0627\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0627\u0644\u0646\u0627\u0633 \u0645\u064f\u0642\u062a\u062f\u0648\u0646 \u0628\u0635\u0644\u0627\u0629 \u0623\u0628\u0650\u064a \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647  - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a.","\u0645\u0639\u0627\u0646\u0649 \u0627\u0644\u062d\u062f\u064a\u062b:","-\u0623\u0633\u0650\u064a\u0641: \u0643\u062b\u064a\u0631 \u0627\u0644\u0628\u0643\u0627\u0621 \u0641\u064a \u0627\u0644\u0635\u0644\u0627\u0629.","-\u0625\u0646\u0651\u064e\u0643\u064f\u0646 \u0644\u0623\u0646\u062a\u064f\u0646\u0651\u064e \u0635\u064e\u0648\u064e\u0627\u062d\u0650\u0628 \u064a\u064f\u0648\u0633\u0641: \u0623\u0649 \u0625\u0638\u0647\u0627\u0631 \u062e\u0644\u0627\u0641 \u0645\u0627 \u064a\u0628\u0637\u0650\u0646\u0651\u064e\u060c \u0648\u0643\u062b\u0631\u0629 \u0625\u0644\u062d\u0627\u062d\u0650\u0647\u0646\u0651\u064e \u0641\u064a \u0637\u0644\u0628 \u0645\u0627 \u064a\u064f\u0631\u0650\u062f\u0646\u0647\u060c \u0648\u0627\u0644\u0642\u0635\u062f \u0623\u0646 \u0623\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0639\u0627\u0626\u0634\u0629 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 \u062e\u0627\u0641\u062a \u0623\u0646 \u064a\u062a\u0634\u0627\u0621\u0645 \u0627\u0644\u0646\u0627\u0633 \u0645\u0646 \u0623\u0628\u064a \u0628\u0643\u0631 \u0644\u0623\u0646\u0647 \u062d\u0644 \u0645\u062d\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa.","-\u064a\u064f\u0647\u0627\u062f\u064e\u0649 \u0628\u064a\u0646 \u0631\u062c\u0644\u064a\u0646: \u064a\u0645\u0634\u0649 \u0645\u064f\u0633\u062a\u0646\u062f\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u0639\u0628\u0627\u0633 \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u0648\u0639\u0644\u064a \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627.","-\u0631\u0650\u062c\u0644\u0627\u0647 \u064a\u062e\u064f\u0637\u0627\u0646: \u062a\u0639\u0645\u0644\u0627\u0646 \u0645\u062b\u0644 \u0627\u0644\u062e\u0637 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0644\u062b\u0642\u0644\u0647 \u0648\u0645\u0631\u0636\u0647 \ufdfa.","-\u0641\u0623\u0648\u0652\u0645\u064e\u0623: \u0623\u0634\u0627\u0631 \u0625\u0644\u064a\u0647 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0623\u0646 \u064a\u0638\u0644 \u0641\u064a \u0645\u0643\u0627\u0646\u0647."],t.s)
