B.aSu=s(["\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u0628\u0627\u0633 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0623\u0628\u0649 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0623\u062d\u062f\u064c \u0641\u064a \u0645\u0642\u0627\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0625\u0644\u0627 \u0623\u0628\u0627 \u0628\u0643\u0631.","\u0648\u0643\u0627\u0646 \u0644\u0628\u0639\u0636 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0623\u0628\u0648\u0627\u0628 \u0635\u063a\u064a\u0631\u0629 \u062a\u064f\u0641\u062a\u062d \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u0646\u0628\u0648\u064a\u060c \u062a\u064f\u0639\u0631\u0641 \u0628\u0627\u0644\u062e\u0648\u062e\u0627\u062a\u060c \u0641\u0623\u0645\u0631 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0641\u064a \u0623\u0648\u0627\u062e\u0631 \u062d\u064a\u0627\u062a\u0647 \u0623\u0646 \u062a\u064f\u063a\u0644\u0642 \u0643\u0644 \u062e\u0648\u062e\u0629\u060c \u0625\u0644\u0627 \u062e\u0648\u062e\u0629 \u0623\u0628\u064a \u0628\u0643\u0631.","\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \u0645\u0650\u0646 \u0623\u0645\u064e\u0646\u0651\u0650 \u0627\u0644\u0646\u0627\u0633 \u0639\u0644\u064a\u0651 \u0641\u064a \u0635\u064f\u062d\u0628\u064e\u062a\u0650\u0647\u0650 \u0648\u0645\u0627\u0644\u0650\u0647\u0650 \u0623\u0628\u0627 \u0628\u0643\u0631\u064d\u060c \u0648\u0644\u0648 \u0643\u064f\u0646\u062a \u0645\u064f\u062a\u062e\u0650\u0630\u064b\u0627 \u062e\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0623\u064f\u0645\u0651\u064e\u062a\u064a \u0644\u0627\u062a\u062e\u064e\u0630\u062a\u064f \u0623\u0628\u0627 \u0628\u0643\u0631\u064d\u060c \u0625\u0644\u0627 \u062e\u064f\u0644\u0651\u064e\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0644\u0627 \u064a\u064e\u0628\u0642\u064a\u0646 \u0641\u064a \u0627\u0644\u0645\u0633\u062c\u062f\u0650 \u062e\u064e\u0648\u062e\u0629\u064c \u0625\u0644\u0627 \u062e\u064e\u0648\u062e\u0629\u064f \u0623\u0628\u064a \u0628\u0643\u0631\u064d - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a."],t.s)
B.RE=new A.a("B2_C6_T3","\u0627\u0644\u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0631\u0628\u0627\u0646\u064a \u0644\u0623\u0628\u064a \u0628\u0643\u0631\u064d \u0644\u062e\u0644\u0627\u0641\u0629 \u0627\u0644\u0646\u0628\u064a \ufdfa",B.aSu)
B.aTs=s(["\u0644\u0645 \u064a\u0643\u0646 \u0627\u062e\u062a\u064a\u0627\u0631 \u0623\u0628\u064a \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0628\u062a\u0643\u0644\u064a\u0641\u064d \u0645\u064f\u0639\u0644\u0646\u064d \u0645\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u0628\u0644 \u0643\u0627\u0646 \u0625\u0639\u062f\u0627\u062f\u064b\u0627 \u0631\u0628\u0627\u0646\u064a\u0651\u064b\u0627 \u0645\u062d\u0643\u0645\u064b\u0627\u060c \u0648\u0623\u0645\u0631\u064e \u0631\u064f\u0634\u062f\u064d \u0647\u064a\u0651\u064e\u0623\u0647 \u0627\u0644\u0644\u0647 \u0644\u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0629\u060c \u0641\u0645\u0627 \u0643\u0627\u0646 \u0623\u062d\u062f\u064c \u0645\u0646 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0628\u0639\u062f\u0647 \u062e\u0644\u064a\u0641\u0629\u064b \u063a\u064a\u0631\u064e \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa .","\u0648\u0642\u062f \u062a\u062c\u0644\u0651\u0649 \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u062d\u064a\u0646 \u0642\u062f\u0651\u0645\u0647 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0625\u0645\u0627\u0645\u064b\u0627 \u0641\u064a \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u0623\u0628\u0642\u0649 \u062e\u0648\u062e\u062a\u0647 \u0645\u0641\u062a\u0648\u062d\u0629\u064b \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062c\u062f\u060c \u0648\u0623\u062b\u0646\u0649 \u0639\u0644\u064a\u0647 \u0628\u0645\u0627 \u0644\u0627 \u064a\u064f\u062b\u0646\u064e\u0649 \u0628\u0647 \u0639\u0644\u0649 \u063a\u064a\u0631\u0647\u060c \u062d\u062a\u0649 \u062a\u0647\u064a\u0623\u062a \u0627\u0644\u0646\u0641\u0648\u0633 \u0644\u062a\u0642\u0628\u0651\u0644\u0647 \u0642\u0627\u0626\u062f\u064b\u0627 \u0628\u0639\u062f \u0631\u062d\u064a\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u064a\u0645\u0636\u064a \u0628\u0627\u0644\u0623\u0645\u0629 \u0639\u0644\u0649 \u0646\u0647\u062c \u0627\u0644\u0646\u0628\u0648\u0629.","\u0625\u0646\u0651\u064e \u0627\u0644\u0646\u0628\u064a \ufdfa \u0644\u0645 \u064a\u0643\u0646 \u0644\u064a\u0645\u0636\u064a \u0628\u0627\u0644\u0631\u0623\u064a \u0641\u064a \u0634\u0624\u0648\u0646 \u0627\u0644\u062f\u0648\u0644\u0629 \u0648\u0623\u0645\u0648\u0631 \u0627\u0644\u062d\u0631\u0628 \u0648\u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u062f\u0648\u0646 \u0645\u0634\u0627\u0648\u0631\u0629\u060c \u0645\u0627 \u0644\u0645 \u064a\u0643\u0646 \u0648\u062d\u064a\u064b\u0627 \u0645\u0646\u0632\u0644\u064b\u0627\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0648\u064e\u0645\u0627 \u0643\u0627\u0646\u064e \u0644\u0650\u0645\u064f\u0624\u0645\u0650\u0646\u064d \u0648\u064e\u0644\u0627 \u0645\u064f\u0624\u0645\u0650\u0646\u064e\u0629\u064d \u0625\u0650\u0630\u0627 \u0642\u064e\u0636\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u0648\u0644\u064f\u0647\u064f \u0623\u064e\u0645\u0631\u064b\u0627 \u0623\u064e\u0646 \u064a\u064e\u0643\u0648\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u062e\u0650\u064a\u064e\u0631\u064e\u0629\u064f \u0645\u0650\u0646 \u0623\u064e\u0645\u0631\u0650\u0647\u0650\u0645\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u062d\u0632\u0627\u0628\u060c \u0623\u0645\u0627 \u0641\u064a\u0645\u0627 \u0633\u0648\u0649 \u0630\u0644\u0643\u060c \u0641\u0625\u0646\u0645\u0627 \u064a\u064f\u0631\u0634\u062f\u060c \u0648\u064a\u0633\u062a\u0634\u064a\u0631\u060c \u0648\u064a\u062a\u0631\u0643 \u0627\u0644\u0623\u0645\u0631 \u0644\u062e\u064a\u0627\u0631 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u064a\u062a\u0634\u0627\u0648\u0631\u0648\u0646 \u0641\u064a\u0647.","\u0644\u0642\u062f \u0631\u0628\u0651\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0623\u0635\u062d\u0627\u0628\u0647 \u0639\u0644\u0649 \u0627\u0644\u062a\u0642\u0648\u0649\u060c \u0648\u063a\u0631\u0633 \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645 \u0627\u0644\u0639\u0642\u064a\u062f\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629\u060c \u0648\u0646\u0642\u0651\u0649 \u0646\u0641\u0648\u0633\u0647\u0645 \u0645\u0646 \u0634\u0648\u0627\u0626\u0628 \u0627\u0644\u0647\u0648\u0649 \u0648\u062f\u0639\u0648\u0649 \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629\u060c \u0641\u0644\u0645\u0627 \u062c\u0627\u0621 \u0645\u0648\u0642\u0641 \u0648\u0641\u0627\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0644\u0645 \u064a\u062a\u0631\u062f\u062f\u0648\u0627\u060c \u0648\u0644\u0645 \u064a\u062a\u0646\u0627\u0632\u0639\u0648\u0627\u060c \u0628\u0644 \u0627\u062c\u062a\u0645\u0639\u0648\u0627 \u0639\u0644\u0649 \u0623\u0628\u064a \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647."],t.s)
B.a2i=new A.a("B2_C6_T4","\u0645\u0650\u0646 \u0641\u0642\u0647\u0650 \u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0644\u0623\u0628\u064a \u0628\u0643\u0631\u064d",B.aTs)
B.aIj=s(["\u0627\u0634\u062a\u062f\u0651 \u0627\u0644\u0645\u0631\u0636 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0643\u0627\u0646\u062a \u0623\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0639\u0627\u0626\u0634\u0629 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 \u062a\u0645\u0631\u0631 \u0627\u0644\u0645\u0627\u0621 \u0639\u0644\u0649 \u0648\u062c\u0647\u0647 \ufdfa \u062a\u062e\u0641\u064a\u0641\u064b\u0627 \u0644\u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u062d\u0645\u0649\u060c \u0648\u0643\u0627\u0646 \u064a\u0642\u0648\u0644: \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647\u060c \u0625\u0646 \u0644\u0644\u0645\u0648\u062a \u0644\u0633\u0643\u0631\u0627\u062a. \u062b\u0645 \u0645\u062f \u064a\u062f\u0647\u060c \u0648\u0631\u0641\u0639\u0647\u0627 \u0645\u0634\u064a\u0631\u064b\u0627 \u0628\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u062c\u0639\u0644 \u064a\u0642\u0648\u0644: \u0628\u0644 \u0627\u0644\u0631\u0641\u064a\u0642 \u0627\u0644\u0623\u0639\u0644\u0649\u2026 \u062d\u062a\u0649 \u0641\u0627\u0636\u062a \u0631\u0648\u062d\u0647 \ufdfa \u0625\u0644\u0649 \u0627\u0644\u0633\u0645\u0627\u0621.","\u0627\u0631\u062a\u062c\u0651\u062a \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u0643\u0627\u0646\u062a \u0635\u062f\u0645\u0629 \u0634\u062f\u064a\u062f\u0629\u060c \u0648\u0627\u0631\u062a\u0628\u0643 \u0627\u0644\u0635\u062d\u0627\u0628\u0629\u060c \u062d\u062a\u0649 \u0642\u0627\u0644 \u0639\u0645\u0631 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0625\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0645 \u064a\u0645\u062a\u060c \u0648\u0633\u064a\u0639\u0648\u062f \u0643\u0645\u0627 \u0639\u0627\u062f \u0645\u0648\u0633\u0649 \u0625\u0644\u0649 \u0642\u0648\u0645\u0647."],t.s)
