B.aw8=s(["\u0627\u0644\u062f\u0651\u064f\u0639\u0627\u0621 \u064a\u064e\u0635\u0631\u0650\u0641\u064f \u0627\u0644\u0628\u064e\u0644\u0627\u0621\u064e\u060c \u0648\u064a\u064f\u0639\u062a\u064e\u0635\u064e\u0645 \u0628\u0647 \u0645\u0650\u0646 \u0646\u064e\u0632\u064e\u063a\u064e\u0627\u062a\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0637\u0627\u0646\u0650 \u0648\u0623\u064e\u0630\u0627\u0647.","\u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b\u0650 \u064a\u064f\u0631\u0634\u0650\u062f\u064f \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u064f \ufdfa \u0625\u0644\u0649 \u062f\u064f\u0639\u0627\u0621\u064d \u064a\u0642\u0648\u0644\u064f\u0647 \u0627\u0644\u0631\u0651\u064e\u062c\u0644\u064f \u0639\u0646\u062f\u0645\u0627 \u064a\u064f\u0631\u064a\u062f\u064f \u0623\u0646 \u064a\u064f\u062c\u0627\u0645\u0650\u0639\u064e \u0623\u0647\u0644\u064e\u0647\u060c \u0641\u064a\u064e\u0642\u0648\u0644: \xab\u0628\u0627\u0633\u0645\u0650 \u0627\u0644\u0644\u0647\u0650\u060c \u0627\u0644\u0644\u0651\u064e\u0647\u0645\u0651\u064e \u062c\u064e\u0646\u0651\u0650\u0628\u0646\u064a \u0627\u0644\u0634\u0651\u064e\u064a\u0637\u0627\u0646\u064e\u060c \u0648\u062c\u064e\u0646\u0651\u0650\u0628\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0637\u0627\u0646\u064e \u0645\u0627 \u0631\u0632\u064e\u0642\u062a\u064e\u0646\u0627\xbb\u060c \u0623\u064a: \u0627\u0644\u0644\u0647\u064f\u0645\u0651\u064e \u0628\u0627\u0639\u0650\u062f \u0628\u064a\u0646\u064a \u0648\u0628\u064a\u0646 \u0627\u0644\u0634\u0651\u064e\u064a\u0637\u0627\u0646\u0650\u060c \u0648\u0628\u0627\u0639\u0650\u062f \u0628\u064a\u0646\u0647 \u0648\u0628\u064a\u0646 \u0643\u064f\u0644\u0651\u0650 \u0645\u0627 \u0623\u0639\u0637\u064e\u064a\u062a\u064e\u0646\u064e\u0627 \u0625\u064a\u0651\u064e\u0627\u0647 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0644\u064a\u0644\u0629\u0650 \u0645\u0650\u0646 \u0627\u0644\u0648\u064e\u0644\u064e\u062f\u0650\u060c \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062e\u0628\u0650\u0631 \ufdfa \u0639\u0646 \u0641\u0627\u0626\u062f\u0629\u0650 \u0647\u0630\u0627 \u0627\u0644\u062f\u0651\u064f\u0639\u0627\u0621\u0650\u061b \u0648\u0647\u064a \u0623\u0646\u0651\u064e\u0647 \u0644\u0648 \u0642\u064e\u062f\u0651\u064e\u0631 \u0627\u0644\u0644\u0647\u064f \u062a\u0639\u0627\u0644\u064e\u0649 \u0648\u0631\u064f\u0632\u0650\u0642\u064e\u0627 \u0648\u0644\u064e\u062f\u064b\u0627 \u0645\u0650\u0646 \u0647\u0630\u0627 \u0627\u0644\u062c\u0650\u0645\u0627\u0639\u0650\u061b \u0641\u0625\u0646\u0651\u064e \u0630\u0644\u0643 \u0627\u0644\u0648\u0644\u062f\u064e \u064a\u0643\u0648\u0646\u064f \u0641\u064a \u0639\u0650\u0635\u0645\u0629\u0650 \u0627\u0644\u0644\u0647\u0650 \u0645\u064e\u062d\u0641\u0648\u0638\u064b\u0627 \u0645\u0650\u0646 \u0627\u0644\u0634\u0651\u064e\u064a\u0637\u0627\u0646\u0650 \u0645\u064f\u062f\u0651\u064e\u0629\u064e \u062d\u064e\u064a\u0627\u062a\u0650\u0647\u060c \u0641\u0644\u0627 \u064a\u064e\u0645\u064e\u0633\u0651\u064f\u0647 \u0628\u0623\u0630\u064b\u0649\u060c \u0648\u0627\u0644\u0645\u0642\u0635\u0648\u062f\u064f: \u0639\u064e\u062f\u064e\u0645\u064f \u062a\u064e\u0633\u0644\u0651\u064f\u0637 \u0627\u0644\u0634\u064a\u0637\u0627\u0646\u0650 \u0639\u0644\u064a\u0647 \u0628\u0627\u0644\u0643\u064f\u0644\u0651\u0650\u064a\u0651\u064e\u0629\u0650\u060c \u0648\u0623\u0645\u0651\u064e\u0627 \u0627\u0644\u0648\u064e\u0633\u0648\u064e\u0633\u064e\u0629\u064f \u0641\u0625\u0646\u0651\u064e\u0647\u0627 \u0648\u0627\u0642\u0650\u0639\u0629\u064c \u0644\u0643\u0644\u0651\u0650 \u0623\u062d\u062f\u064d.","\u0648\u0641\u064a \u0627\u0644\u062d\u064e\u062f\u064a\u062b\u0650: \u0628\u064a\u0627\u0646\u064f \u0641\u064e\u0636\u0644\u0650 \u0627\u0644\u062f\u0651\u064f\u0639\u0627\u0621\u0650 \u0627\u0644\u0645\u0623\u062b\u0648\u0631\u0650 \u0641\u064a \u0643\u064f\u0644\u0651\u0650 \u0641\u0650\u0639\u0644\u064d\u060c \u0648\u0645\u0646\u0647\u0627 \u062c\u0645\u0627\u0639\u064f \u0627\u0644\u0631\u0651\u064e\u062c\u064f\u0644\u0650 \u0632\u0648\u062c\u062a\u064e\u0647\u060c \u0648\u0641\u064a\u0647: \u0623\u0646\u0651\u064e \u0627\u0644\u0644\u0647\u064e \u0633\u064f\u0628\u062d\u0627\u0646\u064e\u0647 \u064a\u062d\u0641\u064e\u0638\u064f \u0639\u0650\u0628\u0627\u062f\u064e\u0647 \u0628\u0645\u0627 \u064a\u064e\u062f\u0639\u0648\u0646 \u0628\u0647 \u0644\u0623\u0646\u0641\u064f\u0633\u0650\u0647\u0645 \u0623\u0648 \u0644\u0630\u064f\u0631\u0651\u0650\u064a\u0651\u064e\u0627\u062a\u0650\u0647\u0645."],t.s)
B.asp=new A.h("baytHadiths_8","\u062f\u0639\u0627\u0621\u064f \u0627\u0644\u0632\u0648\u062c\u064e\u064a\u0646","\u0639\u064e\u0646 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646\u0650 \u0639\u0628\u0627\u0633\u064d \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u0645\u0627 \u0642\u0627\u0644\u064e: \u0642\u0627\u0644\u064e \u0627\u0644\u0646\u0628\u064a\u064f\u0651 \ufdfa : \u0623\u064e\u0645\u064e\u0627 \u0644\u0648 \u0623\u0646\u0651\u064e \u0623\u062d\u064e\u062f\u064e\u0647\u064f\u0645 \u064a\u064e\u0642\u0648\u0644\u064f \u062d\u0650\u064a\u0646\u064e \u064a\u064e\u0623\u062a\u064a \u0623\u0647\u0644\u064e\u0647\u064f: \u0628\u0627\u0633\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650\u060c \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u062c\u064e\u0646\u0651\u0650\u0628\u0646\u0650\u064a \u0627\u0644\u0634\u0651\u064e\u064a\u0637\u0627\u0646\u064e\u060c \u0648\u062c\u064e\u0646\u0651\u0650\u0628\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0637\u0627\u0646\u064e \u0645\u0627 \u0631\u064e\u0632\u064e\u0642\u062a\u064e\u0646\u0627\u060c \u062b\u064f\u0645\u0651\u064e \u0642\u064f\u062f\u0651\u0650\u0631\u064e \u0628\u064a\u0646\u064e\u0647\u064f\u0645\u0627 \u0641\u064a \u0630\u0644\u0643\u064e\u060c \u0623\u0648 \u0642\u064f\u0636\u0650\u064a\u064e \u0648\u0644\u064e\u062f\u064c\u061b \u0644\u064e\u0645 \u064a\u064e\u0636\u064f\u0631\u0651\u064e\u0647\u064f \u0634\u064e\u064a\u0637\u0627\u0646\u064c \u0623\u0628\u064e\u062f\u064b\u0627 - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a",B.aw8)
