B.ayN=s(["\u0623\u0635\u0628\u062d\u062a \u0627\u0644\u064a\u0647\u0648\u062f\u064a\u0629\u064f \u0645\u062c\u0645\u0648\u0639\u0629\u064b \u0645\u0646 \u0627\u0644\u0637\u0642\u0648\u0633 \u0648\u0627\u0644\u062a\u0642\u0627\u0644\u064a\u062f \u0644\u0627 \u0631\u0648\u062d \u0641\u064a\u0647\u0627 \u0648\u0644\u0627 \u062d\u064a\u0627\u0629\u060c \u0648\u062a\u0623\u062b\u0631\u062a \u0628\u0639\u0642\u0627\u0626\u062f \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u062a\u064a \u062c\u0627\u0648\u0631\u062a\u0647\u0627 \u0648\u0627\u062d\u062a\u0643\u062a \u0628\u0647\u0627 \u0648\u0627\u0644\u062a\u064a \u0648\u0642\u0639\u062a \u062a\u062d\u062a \u0633\u064a\u0637\u0631\u062a\u0647\u0627\u060c \u0641\u0623\u062e\u0630\u062a \u0643\u062b\u064a\u0631\u0627\u064b \u0645\u0646 \u0639\u0627\u062f\u0627\u062a\u0647\u0627 \u0648\u062a\u0642\u0627\u0644\u064a\u062f\u0647\u0627 \u0627\u0644\u0648\u062b\u0646\u064a\u0629 \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629\u060c \u0648\u0642\u062f \u0627\u0639\u062a\u0631\u0641 \u0628\u0630\u0644\u0643 \u0645\u0624\u0631\u062e\u0648 \u0627\u0644\u064a\u0647\u0648\u062f \u0623\u0646\u0641\u0633\u064f\u0647\u0645.","\u0648\u062c\u0627\u0621 \u0641\u064a \u062f\u0627\u0626\u0631\u0629 \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0627\u0644\u064a\u0647\u0648\u062f\u064a\u0629: \u0625\u0646 \u0633\u064e\u062e\u064e\u0637\u064e \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0648\u063a\u0636\u0628\u064e\u0647\u0645 \u0639\u0644\u0649 \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u064a\u062f\u0644 \u0639\u0644\u0649 \u0623\u0646 \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0648\u0627\u0644\u0622\u0644\u0647\u0629 \u0643\u0627\u0646\u062a \u0642\u062f \u062a\u0633\u0631\u064e\u0651\u0628\u062a \u0625\u0644\u0649 \u0646\u0641\u0648\u0633 \u0627\u0644\u0625\u0633\u0631\u0627\u0626\u064a\u0644\u064a\u064a\u0646\u060c \u0648\u0644\u0645 \u062a\u064f\u0633\u062a\u0623\u0635\u064e\u0644 \u0634\u0623\u0641\u062a\u064f\u0647\u0627 \u0625\u0644\u0649 \u0623\u064a\u0627\u0645 \u0631\u062c\u0648\u0639\u0647\u0645 \u0645\u0646 \u0627\u0644\u062c\u0644\u0627\u0621 \u0648\u0627\u0644\u0646\u0641\u064a \u0641\u064a \u0628\u0627\u0628\u0644\u060c \u0648\u0642\u062f \u0627\u0639\u062a\u0642\u062f\u0648\u0627 \u0645\u0639\u062a\u0642\u062f\u0627\u062a \u062e\u0631\u0627\u0641\u064a\u0629 \u0648\u0634\u0631\u0643\u064a\u0629\u060c \u0648\u0625\u0646 \u0627\u0644\u062a\u0644\u0645\u0648\u062f \u0623\u064a\u0636\u0627\u064b \u064a\u0634\u0647\u062f \u0628\u0623\u0646 \u0627\u0644\u0648\u062b\u0646\u064a\u0629\u064e \u0643\u0627\u0646\u062a \u0641\u064a\u0647\u0627 \u062c\u0627\u0630\u0628\u064a\u0629\u064c \u062e\u0627\u0635\u0629 \u0644\u0644\u064a\u0647\u0648\u062f.","\u0648\u0642\u062f \u0648\u0635\u0644 \u0627\u0644\u0645\u062c\u062a\u0645\u0639\u064f \u0627\u0644\u064a\u0647\u0648\u062f\u064a \u0642\u0628\u0644 \u0627\u0644\u0628\u0639\u062b\u0629 \u0627\u0644\u0645\u062d\u0645\u062f\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u0627\u0646\u062d\u0637\u0627\u0637 \u0627\u0644\u0639\u0642\u0644\u064a \u0648\u0641\u0633\u0627\u062f \u0627\u0644\u0630\u0648\u0642 \u0627\u0644\u062f\u064a\u0646\u064a\u060c \u0641\u0625\u0630\u0627 \u0637\u0627\u0644\u0639\u062a\u064e \u062a\u0644\u0645\u0648\u062f \u0628\u0627\u0628\u0644 \u0627\u0644\u0630\u064a \u064a\u064f\u0628\u0627\u0644\u063a \u0627\u0644\u064a\u0647\u0648\u062f \u0641\u064a \u062a\u0642\u062f\u064a\u0633\u0647\u060c \u0648\u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u0645\u064f\u062a\u062f\u0627\u0648\u064e\u0644\u0627\u064b \u0628\u064a\u0646\u0647\u0645 \u0641\u064a \u0627\u0644\u0642\u0631\u0646 \u0627\u0644\u0633\u0627\u062f\u0633 \u0627\u0644\u0645\u0633\u064a\u062d\u064a\u060c \u0648\u062c\u062f\u062a\u064e \u0641\u064a\u0647 \u0646\u0645\u0627\u0630\u062c\u064e \u063a\u0631\u064a\u0628\u0629 \u0645\u0646 \u062e\u0641\u0629 \u0627\u0644\u0639\u0642\u0644 \u0648\u0633\u064f\u062e\u0641 \u0627\u0644\u0642\u0648\u0644\u060c \u0648\u0627\u0644\u0627\u062c\u062a\u0631\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u0639\u0628\u062b \u0628\u0627\u0644\u062d\u0642\u0627\u0626\u0642 \u0648\u0627\u0644\u062a\u0644\u0627\u0639\u0628 \u0628\u0627\u0644\u062f\u064a\u0646 \u0648\u0627\u0644\u0639\u0642\u0644."],t.s)
