B.aRm=s(["\u0648\u0643\u0630\u0644\u0643 \u0646\u0634\u0628\u062a \u062d\u0631\u0628 \u062f\u0627\u062d\u0650\u0633 \u0648\u0627\u0644\u063a\u064e\u0628\u0631\u0627\u0621 \u0628\u064a\u0646 \u0642\u0628\u064a\u0644\u062a\u064e\u064a \u0639\u064e\u0628\u0633 \u0648\u0630\u064f\u0628\u064a\u0627\u0646\u060c \u0641\u0631\u0639\u064e\u064a \u063a\u064e\u0637\u064e\u0641\u0627\u0646\u060c \u0648\u0643\u0627\u0646\u062a \u0634\u0631\u0627\u0631\u062a\u0647\u0627 \u0633\u0628\u0627\u0642\u064b\u0627 \u0623\u062c\u0631\u0627\u0647 \u0642\u064e\u064a\u0633 \u0628\u0646 \u0632\u064f\u0647\u064e\u064a\u0631 \u0628\u0641\u0631\u0633\u0647 \u062f\u0627\u062d\u0650\u0633 \u0636\u062f \u0641\u0631\u0633 \u062d\u064f\u0630\u064e\u064a\u0641\u0629 \u0628\u0646 \u0628\u064e\u062f\u0631 \u0627\u0644\u063a\u064e\u0628\u0631\u0627\u0621 \u0631\u0647\u0627\u0646\u064b\u0627 \u0639\u0644\u0649 \u0645\u0627\u0626\u0629 \u0628\u0639\u064a\u0631.","\u0641\u0644\u0645\u0627 \u0623\u064a\u0642\u0646 \u062d\u064f\u0630\u064e\u064a\u0641\u0629 \u0623\u0646 \u062f\u0627\u062d\u0633\u064b\u0627 \u0633\u0627\u0628\u0642\u064c \u0644\u0627 \u0645\u062d\u0627\u0644\u0629 \u062f\u0633\u064e\u0651 \u0631\u062c\u0627\u0644\u064b\u0627 \u0643\u064e\u0645\u064e\u0646\u0648\u0627 \u0641\u064a \u0627\u0644\u0634\u0650\u0651\u0639\u0627\u0628 \u0641\u0636\u0631\u0628\u0648\u0627 \u0648\u062c\u0647\u0647 \u0641\u062a\u0623\u062e\u0631\u060c \u0648\u0633\u0628\u0642\u062a \u0627\u0644\u063a\u064e\u0628\u0631\u0627\u0621\u060c \u0641\u0644\u0645\u0627 \u0627\u0646\u0643\u0634\u0641 \u0627\u0644\u063a\u062f\u0631 \u0631\u0641\u0636 \u0642\u064e\u064a\u0633 \u0627\u0644\u0646\u062a\u064a\u062c\u0629\u060c \u0641\u062a\u0644\u0627\u0637\u0645 \u0627\u0644\u0641\u0631\u064a\u0642\u0627\u0646 \u0628\u0627\u0644\u0623\u064a\u062f\u064a \u0623\u0648\u0644\u064b\u0627 \u062d\u062a\u0649 \u0644\u0637\u0645 \u0645\u0627\u0644\u0650\u0643 \u0628\u0646 \u0632\u064f\u0647\u064e\u064a\u0631 \u0623\u062e\u0648 \u0642\u064e\u064a\u0633 \u0648\u062c\u0647 \u0627\u0644\u063a\u064e\u0628\u0631\u0627\u0621\u060c \u0641\u0631\u062f\u0651 \u062d\u064e\u0645\u064e\u0644 \u0628\u0646 \u0628\u064e\u062f\u0631 \u0627\u0644\u0644\u0637\u0645\u0629 \u0628\u0645\u062b\u0644\u0647\u0627.","\u0648\u0638\u0644\u064e\u0651 \u0627\u0644\u0634\u0631\u064f\u0651 \u0643\u0627\u0645\u0646\u064b\u0627 \u062d\u062a\u0649 \u0642\u062a\u0644\u062a \u0628\u0646\u0648 \u0628\u064e\u062f\u0631 \u0645\u0627\u0644\u0650\u0643\u064b\u0627 \u063a\u062f\u0631\u064b\u0627 \u0648\u0647\u0648 \u0646\u0627\u0632\u0644\u064c \u0628\u064a\u0646\u0647\u0645 \u0622\u0645\u0646\u064b\u0627\u060c \u0641\u062b\u0627\u0631 \u0642\u064e\u064a\u0633 \u0644\u062f\u0645 \u0623\u062e\u064a\u0647 \u0648\u0642\u0627\u062f \u0639\u064e\u0628\u0633\u064b\u0627 \u0641\u064a \u062d\u0631\u0628\u064d \u0636\u0631\u0648\u0633\u064d \u0636\u062f \u0630\u064f\u0628\u064a\u0627\u0646\u060c \u0641\u062a\u0648\u0627\u0644\u062a \u0627\u0644\u0648\u0642\u0627\u0626\u0639 \u0623\u0631\u0628\u0639\u064a\u0646 \u0639\u0627\u0645\u064b\u0627 \u0623\u0638\u0647\u0631 \u0641\u064a\u0647\u0627 \u0639\u064e\u0646\u062a\u0631\u0629 \u0628\u0646 \u0634\u064e\u062f\u0627\u062f \u0628\u0623\u0633\u064b\u0627 \u0636\u064f\u0631\u0628 \u0628\u0647 \u0627\u0644\u0645\u062b\u0644\u060c \u062d\u062a\u0649 \u0623\u0646\u0647\u0643\u062a \u0627\u0644\u062d\u0631\u0628\u064f \u0627\u0644\u0642\u0628\u064a\u0644\u062a\u064a\u0646 \u0648\u0623\u0641\u0646\u062a \u062e\u064a\u0631\u0629 \u0641\u0631\u0633\u0627\u0646\u0647\u0645\u0627\u060c \u0641\u0642\u0627\u0645 \u0627\u0644\u062d\u0627\u0631\u062b \u0628\u0646 \u0639\u064e\u0648\u0641 \u0648\u0647\u064e\u0631\u0650\u0645 \u0628\u0646 \u0633\u0650\u0646\u0627\u0646\u060c \u0633\u064a\u0651\u062f\u0627 \u0628\u0646\u064a \u0645\u064f\u0631\u064e\u0651\u0629 \u0645\u0646 \u0630\u064f\u0628\u064a\u0627\u0646\u060c \u0641\u062a\u062d\u0645\u0651\u0644\u0627 \u062f\u064a\u0627\u062a \u0627\u0644\u0642\u062a\u0644\u0649 \u0645\u0646 \u0623\u0645\u0648\u0627\u0644\u0647\u0645\u0627 \u0648\u0633\u0639\u064a\u0627 \u0628\u0627\u0644\u0635\u0644\u062d \u062d\u062a\u0649 \u0623\u0637\u0641\u0622 \u0646\u0627\u0631 \u0627\u0644\u0641\u062a\u0646\u0629\u060c \u0641\u062e\u0644\u064e\u0651\u062f \u0632\u064f\u0647\u064e\u064a\u0631 \u0628\u0646 \u0623\u0628\u064a \u0633\u064f\u0644\u0645\u0649 \u0635\u0646\u064a\u0639\u064e\u0647\u0645\u0627 \u0641\u064a \u0645\u0639\u0644\u064e\u0651\u0642\u062a\u0647 \u0627\u0644\u0645\u0634\u0647\u0648\u0631\u0629."],t.s)
