B.avm=s(["\u062a\u0642\u0648\u0644 \u062d\u0644\u064a\u0645\u0629: \u0641\u0623\u062e\u0630\u062a\u064f\u0647 \u0648\u0623\u062a\u064a\u062a\u064f \u0628\u0647 \u0627\u0644\u0631\u064e\u0651\u062d\u0644\u060c \u0641\u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0647\u0648 \u0625\u0644\u0627 \u0623\u0646 \u0623\u062a\u064a\u062a\u064f \u0628\u0647 \u0627\u0644\u0631\u064e\u0651\u062d\u0644\u064e\u060c \u0641\u0623\u0645\u0633\u064a\u062a\u064f \u0648\u0642\u062f \u0623\u0642\u0628\u0644 \u062b\u062f\u064a\u0627\u064a \u0628\u0627\u0644\u0644\u0628\u0646\u060c \u0641\u0623\u0631\u0648\u064a\u062a\u064f\u0647 \u0648\u0623\u0631\u0648\u064a\u062a\u064f \u0623\u062e\u0627\u0647\u060c \u0648\u0642\u0627\u0645\u064e \u0623\u0628\u0648\u0647 \u0625\u0644\u0649 \u0634\u0627\u0631\u0641\u0650\u0646\u0627 \u062a\u0644\u0643 \u064a\u0644\u0645\u0633\u064f\u0647\u0627 \u0641\u0625\u0630\u0627 \u0647\u064a \u062d\u0627\u0641\u0644\u064c \u0643\u062b\u064a\u0631\u0629\u064f \u0627\u0644\u0644\u0628\u0646\u060c \u0641\u062d\u0644\u064e\u0628\u064e\u0647\u0627 \u0641\u0623\u0631\u0648\u0627\u0646\u0627 \u0648\u0631\u0648\u0650\u064a\u064e\u060c \u0641\u0642\u0627\u0644: \u064a\u0627 \u062d\u0644\u064a\u0645\u0629\u060c \u062a\u0639\u0644\u0645\u064a\u0646 \u0648\u0627\u0644\u0644\u0647 \u0644\u0642\u062f \u0623\u0635\u0628\u0646\u0627 \u0646\u064e\u0633\u0645\u064e\u0629\u064b \u0645\u0628\u0627\u0631\u0643\u0629\u060c \u0648\u0644\u0642\u062f \u0623\u0639\u0637\u0649 \u0627\u0644\u0644\u0647\u064f \u0639\u0644\u064a\u0647\u0627 \u0645\u0627 \u0644\u0645 \u0646\u062a\u0645\u0646\u064e\u0651\u060c \u0642\u0627\u0644\u062a: \u0641\u0628\u0650\u062a\u0646\u0627 \u0628\u062e\u064a\u0631\u0650 \u0644\u064a\u0644\u0629\u064d \u0634\u0650\u0628\u0627\u0639\u064b\u0627\u060c \u0648\u0643\u0646\u0627 \u0644\u0627 \u0646\u0646\u0627\u0645\u064f \u0644\u064a\u0644\u064e\u0646\u0627 \u0645\u0639 \u0635\u0628\u064a\u0650\u0651\u0646\u0627.","\u0627\u0644\u0645\u0639\u0627\u0646\u0649: [ \u0648\u0623\u062a\u064a\u062a\u064f \u0628\u0647: \u0648\u062c\u0626\u062a\u064f \u0628\u0647 | \u0627\u0644\u0631\u064e\u0651\u062d\u0644: \u0627\u0644\u0645\u0646\u0632\u0644 \u0623\u0648 \u0627\u0644\u0645\u0643\u0627\u0646 \u0627\u0644\u0630\u064a \u064a\u064f\u0642\u064a\u0645 \u0641\u064a\u0647 \u0627\u0644\u0634\u062e\u0635| \u0641\u0623\u0631\u0648\u064a\u062a\u064f\u0647: \u0641\u0623\u0634\u0628\u0639\u062a\u064f\u0647 \u0634\u0631\u0628\u064b\u0627 \u0645\u0646 \u0627\u0644\u0644\u0628\u0646 \u062d\u062a\u0649 \u0627\u0631\u062a\u0648\u0649 | \u0634\u0627\u0631\u0641\u0650\u0646\u0627: \u0646\u0627\u0642\u062a\u0650\u0646\u0627 \u0627\u0644\u0645\u064f\u0633\u0650\u0646\u064e\u0651\u0629 | \u0635\u0628\u064a\u0650\u0651\u0646\u0627: \u0637\u0641\u0644\u0650\u0646\u0627 \u0627\u0644\u0631\u0636\u064a\u0639 ].","\u062b\u0645 \u0627\u063a\u062a\u062f\u064e\u064a\u0646\u0627 \u0631\u0627\u062c\u0639\u064a\u0646 \u0625\u0644\u0649 \u0628\u0644\u0627\u062f\u0646\u0627 \u0623\u0646\u0627 \u0648\u0635\u0648\u0627\u062d\u0628\u064a\u060c \u0641\u0631\u0643\u0628\u062a\u064f \u0623\u062a\u0627\u0646\u064a \u0627\u0644\u0642\u0645\u0631\u0627\u0621 \u0648\u062d\u0645\u064e\u0644\u062a\u064f\u0647 \u0645\u0639\u064a\u060c \u0641\u0648\u0627\u0644\u0630\u064a \u0646\u0641\u0633\u064f \u062d\u0644\u064a\u0645\u0629 \u0628\u064a\u062f\u0647 \u0644\u0642\u0637\u064e\u0639\u062a\u064f \u0627\u0644\u0631\u064e\u0651\u0643\u0628\u064e \u062d\u062a\u0649 \u0625\u0646 \u0627\u0644\u0646\u0633\u0648\u0629 \u0644\u064e\u064a\u064e\u0642\u064f\u0644\u0646\u064e: \u0623\u064e\u0645\u0633\u0650\u0643\u064a \u0639\u0644\u064a\u0646\u0627\u060c \u0623\u0647\u0630\u0647 \u0623\u062a\u0627\u0646\u064f\u0643\u0650 \u0627\u0644\u062a\u064a \u062e\u0631\u062c\u062a\u0650 \u0639\u0644\u064a\u0647\u0627\u061f \u0641\u0642\u0644\u062a\u064f: \u0646\u0639\u0645\u060c \u0641\u0642\u0627\u0644\u0648\u0627: \u0625\u0646\u0647\u0627 \u0643\u0627\u0646\u062a \u0642\u062f \u0623\u064e\u062f\u0645\u064e\u062a \u062d\u064a\u0646 \u0623\u0642\u0628\u064e\u0644\u0646\u0627 \u0641\u0645\u0627 \u0634\u0623\u0646\u064f\u0647\u0627\u061f \u0641\u0642\u0644\u062a\u064f: \u0648\u0627\u0644\u0644\u0647 \u062d\u0645\u064e\u0644\u062a\u064f \u0639\u0644\u064a\u0647\u0627 \u063a\u0644\u0627\u0645\u064b\u0627 \u0645\u0628\u0627\u0631\u0643\u064b\u0627.","\u0641\u062e\u0631\u064e\u062c\u0646\u0627 \u0641\u0645\u0627 \u0632\u0627\u0644 \u064a\u0632\u064a\u062f\u064f\u0646\u0627 \u0627\u0644\u0644\u0647 \u0641\u064a \u0643\u0644 \u064a\u0648\u0645 \u062e\u064a\u0631\u064b\u0627\u060c \u062d\u062a\u0649 \u0642\u064e\u062f\u0650\u0645\u0646\u0627 \u0648\u0627\u0644\u0628\u0644\u0627\u062f\u064f \u0633\u0646\u0629\u060c \u0648\u0644\u0642\u062f \u0643\u0627\u0646 \u0631\u064f\u0639\u0627\u062a\u064f\u0646\u0627 \u064a\u064f\u0633\u0631\u0650\u0651\u062d\u0648\u0646 \u062b\u0645 \u064a\u0631\u0648\u062d\u0648\u0646\u060c \u0641\u062a\u0631\u0648\u062d\u064f \u0623\u063a\u0646\u0627\u0645\u064f \u0628\u0646\u064a \u0633\u0639\u062f \u062c\u064a\u0627\u0639\u064b\u0627\u060c \u0648\u062a\u0631\u0648\u062d\u064f \u063a\u0646\u064e\u0645\u064a \u0628\u0650\u0637\u0627\u0646\u064b\u0627 \u062d\u064f\u0641\u064e\u0651\u0644\u064b\u0627 \u0641\u0646\u064e\u062d\u0644\u064f\u0628\u064f \u0648\u0646\u0634\u0631\u0628\u060c \u0641\u064a\u0642\u0648\u0644\u0648\u0646: \u0645\u0627 \u0634\u0623\u0646\u064f \u063a\u0646\u0645 \u0627\u0644\u062d\u0627\u0631\u062b \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0639\u0632\u0649 \u0648\u063a\u0646\u0645 \u062d\u0644\u064a\u0645\u0629 \u062a\u0631\u0648\u062d\u064f \u0634\u0650\u0628\u0627\u0639\u064b\u0627 \u062d\u064f\u0641\u064e\u0651\u0644\u064b\u0627 \u0648\u062a\u0631\u0648\u062d\u064f \u063a\u0646\u0645\u064f\u0643\u0645 \u062c\u064a\u0627\u0639\u064b\u0627\u060c \u0648\u064a\u0644\u064e\u0643\u0645 \u0627\u0633\u0631\u064e\u062d\u0648\u0627 \u062d\u064a\u062b \u062a\u0633\u0631\u062d\u064f \u063a\u0646\u0645\u064f \u0631\u064f\u0639\u0627\u0626\u0647\u0645\u060c \u0641\u064a\u064e\u0633\u0631\u064e\u062d\u0648\u0646 \u0645\u0639\u0647\u0645 \u0641\u0645\u0627 \u062a\u0631\u0648\u062d\u064f \u0625\u0644\u0627 \u062c\u064a\u0627\u0639\u064b\u0627 \u0643\u0645\u0627 \u0643\u0627\u0646\u062a\u060c \u0648\u062a\u0631\u062c\u0639\u064f \u063a\u0646\u0645\u064a \u0643\u0645\u0627 \u0643\u0627\u0646\u062a.","\u0627\u0644\u0645\u0639\u0627\u0646\u0649: [\u0627\u063a\u062a\u062f\u064e\u064a\u0646\u0627: \u062e\u0631\u062c\u0646\u0627 \u0641\u064a \u0627\u0644\u0635\u0628\u0627\u062d \u0627\u0644\u0628\u0627\u0643\u0631 | \u0623\u064e\u0645\u0633\u0650\u0643\u064a \u0639\u0644\u064a\u0646\u0627: \u062a\u0645\u0647\u064e\u0651\u0644\u064a \u0648\u0627\u0646\u062a\u0638\u0631\u064a\u0646\u0627 (\u0627\u0637\u0644\u0628\u0646 \u0645\u0646\u0647\u0627 \u0623\u0646 \u062a\u064f\u0628\u0637\u0626 \u0633\u064a\u0631\u0647\u0627 \u0644\u062a\u0644\u062d\u0642 \u0628\u0647\u0646\u064e\u0651) | \u0628\u0650\u0637\u0627\u0646\u064b\u0627: \u0627\u0644\u0645\u0645\u062a\u0644\u0626\u0629\u064f \u0627\u0644\u0628\u0637\u0648\u0646 | \u062d\u064f\u0641\u064e\u0651\u0644\u064b\u0627: \u0643\u062b\u064a\u0631\u0627\u062a\u064f \u0627\u0644\u0644\u0628\u0646 ].","\u0648\u0643\u0627\u0646 \u064a\u0634\u064f\u0628\u064f\u0651 \u0634\u0628\u0627\u0628\u064b\u0627 \u0645\u0627 \u064a\u064e\u0634\u064f\u0628\u064f\u0651\u0647 \u0623\u062d\u062f\u064c \u0645\u0646 \u0627\u0644\u063a\u0650\u0644\u0645\u0627\u0646\u060c \u064a\u0634\u064f\u0628\u064f\u0651 \u0641\u064a \u0627\u0644\u064a\u0648\u0645 \u0634\u0628\u0627\u0628\u064e \u0627\u0644\u0633\u0646\u0629\u060c \u0641\u0644\u0645\u0627 \u0627\u0633\u062a\u0643\u0645\u0644 \u0633\u0646\u062a\u064a\u0646 \u0623\u0642\u062f\u064e\u0645\u0646\u0627\u0647 \u0645\u0643\u0629 \u0623\u0646\u0627 \u0648\u0623\u0628\u0648\u0647\u060c \u0641\u0642\u0644\u0646\u0627: \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u0646\u064f\u0641\u0627\u0631\u0642\u064f\u0647 \u0623\u0628\u062f\u064b\u0627 \u0648\u0646\u062d\u0646 \u0646\u0633\u062a\u0637\u064a\u0639\u060c \u0641\u0644\u0645\u0627 \u0623\u062a\u064e\u064a\u0646\u0627 \u0623\u0645\u064e\u0651\u0647 -\u0622\u0645\u0646\u0629 \u0628\u0646\u062a \u0648\u0647\u0628- \u0642\u0644\u0646\u0627: \u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0631\u0623\u064e\u064a\u0646\u0627 \u0635\u0628\u064a\u064b\u0651\u0627 \u0642\u0637 \u0623\u0639\u0638\u0645\u064e \u0628\u0631\u0643\u0629\u064b \u0645\u0646\u0647\u060c \u0648\u0625\u0646\u0627 \u0646\u062a\u062e\u0648\u064e\u0651\u0641\u064f \u0639\u0644\u064a\u0647 \u0648\u0628\u0627\u0621\u064e \u0645\u0643\u0629 \u0648\u0623\u0633\u0642\u0627\u0645\u064e\u0647\u0627\u060c \u0641\u062f\u064e\u0639\u064a\u0647 \u0646\u0631\u062c\u0639\u064f \u0628\u0647 \u062d\u062a\u0649 \u062a\u064e\u0628\u0631\u0626\u064a \u0645\u0646 \u062f\u0627\u0626\u0643\u0650\u060c \u0641\u0644\u0645 \u0646\u0632\u064e\u0644 \u0628\u0647\u0627 \u062d\u062a\u0649 \u0623\u064e\u0630\u0650\u0646\u064e\u062a."],t.s)
