B.aHR=s(["\u0644\u0645\u0627 \u0631\u062c\u0639\u062a \u0642\u0631\u064a\u0634 \u0645\u0646 \u062d\u0631\u0628 \u0627\u0644\u0641\u062c\u0627\u0631\u060c \u0643\u0627\u0646 \u0631\u062c\u0644\u064c \u0645\u0646 \u0632\u064f\u0628\u064a\u062f -\u0628\u0644\u062f \u0628\u0627\u0644\u064a\u0645\u0646- \u0642\u062f \u0642\u064e\u062f\u0650\u0645 \u0645\u0643\u0629 \u0628\u0628\u0636\u0627\u0639\u0629 \u0641\u0627\u0634\u062a\u0631\u0627\u0647\u0627 \u0645\u0646\u0647 \u0627\u0644\u0639\u0627\u0635 \u0628\u0646 \u0648\u0627\u0626\u0644 \u0648\u0645\u0646\u0639\u0647 \u062d\u0642\u0647\u060c \u0641\u0627\u0633\u062a\u0639\u062f\u0649 \u0627\u0644\u0632\u064f\u0651\u0628\u064a\u062f\u064a\u064f\u0651 \u0623\u0634\u0631\u0627\u0641 \u0642\u0631\u064a\u0634 \u0641\u0644\u0645 \u064a\u064f\u0639\u064a\u0646\u0648\u0647 \u0644\u0645\u0643\u0627\u0646\u0629 \u0627\u0644\u0639\u0627\u0635 \u0628\u064a\u0646\u0647\u0645\u060c \u0641\u0648\u0642\u0641 \u0639\u0646\u062f \u0627\u0644\u0643\u0639\u0628\u0629 \u0648\u0627\u0633\u062a\u063a\u0627\u062b \u0628\u0622\u0644 \u0641\u0647\u0631 \u0648\u0623\u0647\u0644 \u0627\u0644\u0645\u0631\u0648\u0621\u0629\u060c \u0648\u0646\u0627\u062f\u0649 \u0628\u0623\u0639\u0644\u0649 \u0635\u0648\u062a\u0647:","\u064a\u0627 \u0622\u0644 \u0641\u0647\u0631 \u0644\u0645\u0638\u0644\u0648\u0645 \u0628\u0636\u0627\u0639\u062a\u0647 .. \u0628\u0628\u0637\u0646 \u0645\u0643\u0629 \u0646\u0627\u0626\u064a \u0627\u0644\u062f\u0627\u0631 \u0648\u0627\u0644\u0646\u0641\u0631","\u0648\u0645\u062d\u0631\u0645 \u0623\u0634\u0639\u062b \u0644\u0645 \u064a\u0642\u0636 \u0639\u0645\u0631\u062a\u0647 .. \u064a\u0627 \u0644\u0644\u0631\u062c\u0627\u0644 \u0648\u0628\u064a\u0646 \u0627\u0644\u062d\u0650\u062c\u0631 \u0648\u0627\u0644\u062d\u064e\u062c\u064e\u0631","\u0625\u0646 \u0627\u0644\u062d\u0631\u0627\u0645 \u0644\u0645 \u062a\u0645\u062a \u0643\u0631\u0627\u0645\u062a\u0647 .. \u0648\u0644\u0627 \u062d\u0631\u0645 \u0644\u062b\u0648\u0628 \u0627\u0644\u0641\u0627\u062c\u0631 \u0627\u0644\u063a\u064f\u062f\u0631","\u0641\u0642\u0627\u0645 \u0627\u0644\u0632\u0628\u064a\u0631 \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u0648\u0642\u0627\u0644: \u0645\u0627 \u0644\u0647\u0630\u0627 \u0645\u062a\u0631\u0643\u060c \u0641\u0627\u062c\u062a\u0645\u0639\u062a \u0628\u0646\u0648 \u0647\u0627\u0634\u0645 \u0648\u0628\u0646\u0648 \u0632\u0647\u0631\u0629 \u0648\u0628\u0646\u0648 \u062a\u064e\u064a\u0645 \u0628\u0646 \u0645\u0631\u0629 \u0641\u064a \u062f\u0627\u0631 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u062c\u062f\u0639\u0627\u0646\u060c \u0641\u0635\u0646\u0639 \u0644\u0647\u0645 \u0637\u0639\u0627\u0645\u064b\u0627\u060c \u0648\u062a\u062d\u0627\u0644\u0641\u0648\u0627 \u0641\u064a \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u062d\u0631\u0627\u0645 \u0648\u0647\u0648 \u0630\u0648 \u0627\u0644\u0642\u0639\u062f\u0629\u060c \u0641\u062a\u0639\u0627\u0642\u062f\u0648\u0627 \u0648\u062a\u0639\u0627\u0647\u062f\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0644\u064a\u0643\u0648\u0646\u064f\u0646\u0651 \u064a\u062f\u064b\u0627 \u0648\u0627\u062d\u062f\u0629 \u0645\u0639 \u0627\u0644\u0645\u0638\u0644\u0648\u0645 \u0639\u0644\u0649 \u0627\u0644\u0638\u0627\u0644\u0645 \u062d\u062a\u0649 \u064a\u064f\u0631\u064e\u062f\u064e\u0651 \u0625\u0644\u064a\u0647 \u062d\u0642\u0647 \u0645\u0627 \u0628\u064e\u0644\u064e\u0651 \u0628\u062d\u0631\u064c \u0635\u0648\u0641\u0629\u064b -\u064a\u0639\u0646\u064a \u0625\u0644\u0649 \u0627\u0644\u0623\u0628\u062f-\u060c \u0648\u0645\u0627 \u0628\u0642\u064a \u062c\u064e\u0628\u064e\u0644\u0627 \u062b\u0628\u064a\u0631 \u0648\u062d\u0631\u0627\u0621 \u0645\u0643\u0627\u0646\u0647\u0645\u0627 -\u0637\u0627\u0644\u0645\u0627 \u0628\u0642\u064a \u0647\u0630\u0627\u0646 \u0627\u0644\u062c\u0628\u0644\u0627\u0646 \u0641\u064a \u0645\u0643\u0627\u0646\u0647\u0645\u0627-\u060c \u062b\u0645 \u0645\u0634\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0639\u0627\u0635 \u0628\u0646 \u0648\u0627\u0626\u0644 \u0641\u0627\u0646\u062a\u0632\u0639\u0648\u0627 \u0645\u0646\u0647 \u0633\u0644\u0639\u0629 \u0627\u0644\u0632\u0628\u064a\u062f\u064a \u0648\u062f\u0641\u0639\u0648\u0647\u0627 \u0625\u0644\u064a\u0647\u060c \u0648\u0633\u0645\u0651\u062a \u0642\u0631\u064a\u0634 \u0647\u0630\u0627 \u0627\u0644\u062d\u0644\u0641 \u062d\u0644\u0641 \u0627\u0644\u0641\u0636\u0648\u0644 \u0648\u0642\u0627\u0644\u0648\u0627: \u0644\u0642\u062f \u062f\u062e\u0644 \u0647\u0624\u0644\u0627\u0621 \u0641\u064a \u0641\u0636\u0644 \u0645\u0646 \u0627\u0644\u0623\u0645\u0631.","\u0648\u0642\u0627\u0644 \u0627\u0644\u0632\u0628\u064a\u0631 \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u0644\u0641:","\u0625\u0646 \u0627\u0644\u0641\u0636\u0648\u0644 \u062a\u0639\u0627\u0642\u062f\u0648\u0627 \u0648\u062a\u062d\u0627\u0644\u0641\u0648\u0627 .. \u0623\u0644\u0627 \u064a\u0642\u064a\u0645 \u0628\u0628\u0637\u0646 \u0645\u0643\u0629 \u0638\u0627\u0644\u0645","\u0623\u0645\u0631 \u0639\u0644\u064a\u0647 \u062a\u0639\u0627\u0642\u062f\u0648\u0627 \u0648\u062a\u0648\u0627\u062b\u0642\u0648\u0627 .. \u0641\u0627\u0644\u062c\u0627\u0631 \u0648\u0627\u0644\u0645\u064f\u0639\u062a\u0631\u0651 \u0641\u064a\u0647\u0645 \u0633\u0627\u0644\u0645","\u0627\u0644\u0645\u0639\u062a\u0631: \u0627\u0644\u0632\u0627\u0626\u0631 \u0645\u0646 \u063a\u064a\u0631 \u0627\u0644\u0628\u0644\u0627\u062f","\u0648\u0642\u062f \u062d\u0636\u0631 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0647\u0630\u0627 \u0627\u0644\u062d\u0644\u0641 \u0627\u0644\u0630\u064a \u0647\u064e\u062f\u064e\u0645\u0648\u0627 \u0628\u0647 \u0635\u0631\u062d \u0627\u0644\u0638\u0644\u0645 \u0648\u0631\u0641\u0639\u0648\u0627 \u0628\u0647 \u0645\u0646\u0627\u0631 \u0627\u0644\u062d\u0642\u060c \u0648\u0642\u0627\u0644 \ufdfa: \xab\u0634\u0647\u062f\u062a\u064f \u0645\u0639 \u0639\u0645\u0648\u0645\u062a\u064a \u062d\u0650\u0644\u0641\u064e \u0627\u0644\u0645\u064e\u0637\u064a\u0651\u0650\u0628\u064a\u0646\u060c \u0641\u0645\u0627 \u0623\u064f\u062d\u0650\u0628\u0651\u064f \u0623\u0646 \u0623\u0646\u0643\u064f\u062b\u064e\u0647 \u0648\u0623\u0646\u0651\u064e \u0644\u064a \u062d\u064f\u0645\u0631\u064f \u0627\u0644\u0646\u0651\u064e\u0639\u064e\u0645\u0650\xbb - \u0623\u062e\u0631\u062c\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a.","\u0627\u0644\u0645\u0639\u0627\u0646\u064a: [\u0639\u0645\u0648\u0645\u062a\u064a: \u0623\u0639\u0645\u0627\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa | \u0623\u0646\u0643\u064f\u062b\u064e\u0647: \u0623\u062a\u0631\u0627\u062c\u0639 \u0639\u0646\u0647 | \u062d\u064f\u0645\u0631\u064f \u0627\u0644\u0646\u0651\u064e\u0639\u064e\u0645\u0650: \u0627\u0644\u0625\u0628\u0644 \u0627\u0644\u062d\u0645\u0631\u0627\u0621\u060c \u0648\u0643\u0627\u0646\u062a \u0623\u063a\u0644\u0649 \u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0639\u0631\u0628\u060c \u0648\u062a\u064f\u0636\u0631\u0628 \u0628\u0647\u0627 \u0641\u064a \u0627\u0644\u0623\u0645\u062b\u0627\u0644].","*\u062a\u0646\u0648\u064a\u0647: \u0627\u0644\u062d\u0644\u0641 \u0627\u0644\u0630\u064a \u0634\u0647\u062f\u0647 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0647\u0648 \u062d\u0644\u0641 \u0627\u0644\u0641\u0636\u0648\u0644\u061b \u0648\u0625\u0646\u0645\u0627 \u0633\u0645\u0627\u0647 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0640\u062d\u0644\u0641 \u0627\u0644\u0645\u064e\u0637\u064a\u0651\u0650\u0628\u064a\u0646\u061b \u0644\u0623\u0646 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u062a\u064a \u0639\u0642\u062f\u062a \u062d\u0644\u0641 \u0627\u0644\u0641\u0636\u0648\u0644 \u0647\u064a \u0645\u0646 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u062a\u064a \u0633\u0628\u0642 \u0648\u0623\u0646 \u0639\u0642\u062f\u062a \u062d\u0644\u0641 \u0627\u0644\u0645\u064e\u0637\u064a\u0651\u0650\u0628\u064a\u0646\u060c \u0641\u0646\u0633\u0628 \u0627\u0644\u062d\u0644\u0641 \u0625\u0644\u064a\u0647\u0645\u060c \u0623\u0645\u0627 \u062d\u0644\u0641\u064f \u0627\u0644\u0645\u064e\u0637\u064a\u0651\u0650\u0628\u064a\u0646 \u0641\u0647\u0648 \u062d\u0644\u0641 \u0642\u062f\u064a\u0645 \u0639\u0642\u062f\u062a\u0647 \u0642\u0631\u064a\u0634 \u0642\u0628\u0644 \u0645\u0648\u0644\u062f \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u0639\u0642\u0628 \u0648\u0641\u0627\u0629 \u0642\u064f\u0635\u064e\u064a \u0628\u0646 \u0643\u0644\u0627\u0628 \u0648\u062a\u0646\u0627\u0632\u0639 \u0628\u0646\u0648\u0647 \u0639\u0644\u0649 \u0634\u0631\u0641 \u0627\u0644\u0643\u0639\u0628\u0629 \u0648\u062e\u062f\u0645\u062a\u0647\u0627\u060c \u0641\u062a\u062d\u0627\u0644\u0641\u062a \u0628\u0646\u0648 \u0639\u0628\u062f \u0645\u0646\u0627\u0641 -\u0648\u0641\u064a\u0647\u0645 \u0628\u0646\u0648 \u0647\u0627\u0634\u0645- \u0636\u062f \u0628\u0646\u064a \u0639\u0628\u062f \u0627\u0644\u062f\u0627\u0631\u060c \u0648\u063a\u0645\u0633\u0648\u0627 \u0623\u064a\u062f\u064a\u0647\u0645 \u0641\u064a \u0642\u064e\u0635\u0639\u0629 \u0637\u0650\u064a\u0628 \u0639\u0646\u062f \u0627\u0644\u0643\u0639\u0628\u0629 \u062a\u0648\u0643\u064a\u062f\u064b\u0627 \u0644\u0639\u0647\u062f\u0647\u0645\u060c \u0641\u0633\u064f\u0645\u0651\u0648\u0627 \u0627\u0644\u0645\u064e\u0637\u064a\u0651\u0650\u0628\u064a\u0646."],t.s)
