B.aHU=s(["\u0627\u0647\u062a\u0645\u064e\u0651 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u0641\u064a \u0627\u0644\u0641\u062a\u0631\u0629 \u0627\u0644\u0645\u0643\u064a\u0651\u0629 \u0628\u0642\u0636\u064a\u0629 \u0627\u0644\u0642\u0636\u0627\u0621 \u0648\u0627\u0644\u0642\u062f\u0631\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0644\u0651\u064e \u0634\u064e\u064a\u0621\u064d \u062e\u064e\u0644\u064e\u0642\u0646\u064e\u0627\u0647\u064f \u0628\u0650\u0642\u064e\u062f\u064e\u0631\u064d\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0642\u0645\u0631\u060c \u0648\u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a\u064f\u0651 \ufdfa \u064a\u064e\u063a\u0631\u0650\u0633 \u0641\u064a \u0646\u0641\u0648\u0633 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0642\u0636\u0627\u0621 \u0648\u0627\u0644\u0642\u062f\u0631 \u063a\u064e\u0631\u0633\u0627\u064b \u0631\u0627\u0633\u062e\u0627\u064b.","\u0648\u0643\u0627\u0646 \u0645\u0646 \u062b\u0645\u0631\u0627\u062a \u0647\u0630\u0627 \u0627\u0644\u0641\u0647\u0645 \u0627\u0644\u0635\u062d\u064a\u062d \u0648\u0627\u0644\u0627\u0639\u062a\u0642\u0627\u062f \u0627\u0644\u0631\u0627\u0633\u062e \u0641\u064a \u0642\u0644\u0648\u0628 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u0622\u062b\u0627\u0631\u064c \u0645\u0628\u0627\u0631\u0643\u0629\u064c \u0639\u0627\u062f\u062a \u0639\u0644\u064a\u0647\u0645 \u0628\u062e\u064a\u0631 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u061b \u0641\u0645\u0646\u0647\u0627 \u0639\u0628\u0627\u062f\u0629\u064f \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0639\u0644\u0649 \u0628\u0635\u064a\u0631\u0629\u060c \u0648\u0627\u0644\u0625\u064a\u0645\u0627\u0646\u064f \u0628\u0627\u0644\u0642\u062f\u0631 \u0637\u0631\u064a\u0642\u064f \u0627\u0644\u062e\u0644\u0627\u0635 \u0645\u0646 \u0627\u0644\u0634\u0631\u0643\u060c \u0625\u0630 \u064a\u064f\u0648\u0642\u0650\u0646 \u0627\u0644\u0645\u0624\u0645\u0646 \u0623\u0646 \u0627\u0644\u0646\u0627\u0641\u0639 \u0648\u0627\u0644\u0636\u0627\u0631\u060c \u0648\u0627\u0644\u0645\u064f\u0639\u0650\u0632\u064e\u0651 \u0648\u0627\u0644\u0645\u064f\u0630\u0650\u0644\u064e\u0651\u060c \u0648\u0627\u0644\u0631\u0627\u0641\u0639 \u0648\u0627\u0644\u062e\u0627\u0641\u0636 \u0647\u0648 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0648\u064a\u062a\u0631\u062a\u0628 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0634\u062c\u0627\u0639\u0629\u064c \u0648\u0625\u0642\u062f\u0627\u0645\u061b \u0644\u0623\u0646 \u0627\u0644\u0622\u062c\u0627\u0644 \u0628\u064a\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0643\u0644 \u0646\u0641\u0633\u064d \u0643\u062a\u0627\u0628\u064c \u0645\u064f\u0642\u062f\u064e\u0651\u0631\u060c \u0641\u064a\u064e\u063a\u062f\u0648 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0623\u0647\u0644\u064e \u0635\u0628\u0631\u064d \u0648\u0627\u062d\u062a\u0633\u0627\u0628\u064d \u0648\u0645\u0648\u0627\u062c\u0647\u0629\u064d \u0644\u0644\u0635\u0639\u0627\u0628\u060c \u0645\u0639 \u0633\u0643\u0648\u0646 \u0627\u0644\u0642\u0644\u0628 \u0648\u0637\u0645\u0623\u0646\u064a\u0646\u0629 \u0627\u0644\u0646\u0641\u0633 \u0648\u0631\u0627\u062d\u0629 \u0627\u0644\u0628\u0627\u0644\u060c \u0641\u0636\u0644\u0627\u064b \u0639\u0646 \u0639\u0632\u0629 \u0627\u0644\u0646\u0641\u0633 \u0648\u0627\u0644\u0642\u0646\u0627\u0639\u0629 \u0648\u0627\u0644\u062a\u062d\u0631\u0631 \u0645\u0646 \u0631\u0650\u0642\u0650\u0651 \u0627\u0644\u0645\u062e\u0644\u0648\u0642\u064a\u0646.","\u0648\u0644\u0645 \u062a\u0642\u062a\u0635\u0631 \u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0644\u0623\u0635\u062d\u0627\u0628\u0647 \u0639\u0644\u0649 \u062a\u0639\u0644\u064a\u0645\u0647\u0645 \u0623\u0631\u0643\u0627\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0627\u0644\u0633\u062a\u0629\u060c \u0628\u0644 \u0635\u062d\u064e\u0651\u062d \u0639\u0646\u062f\u0647\u0645 \u0643\u062b\u064a\u0631\u0627\u064b \u0645\u0646 \u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0648\u0627\u0644\u062a\u0635\u0648\u0631\u0627\u062a \u0648\u0627\u0644\u0627\u0639\u062a\u0642\u0627\u062f\u0627\u062a \u0639\u0646 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u0627\u0644\u062d\u064a\u0627\u0629 \u0648\u0627\u0644\u0643\u0648\u0646 \u0648\u0627\u0644\u0639\u0644\u0627\u0642\u0629 \u0628\u064a\u0646\u0647\u0645\u0627\u060c \u0644\u064a\u0633\u064a\u0631 \u0627\u0644\u0645\u0633\u0644\u0645 \u0639\u0644\u0649 \u0646\u0648\u0631\u064d \u0645\u0646 \u0627\u0644\u0644\u0647\u060c \u064a\u064f\u062f\u0631\u0650\u0643 \u0647\u062f\u0641\u064e \u0648\u062c\u0648\u062f\u0647 \u0641\u064a \u0627\u0644\u062d\u064a\u0627\u0629\u060c \u0648\u064a\u064f\u062d\u0642\u0650\u0651\u0642 \u0645\u0627 \u0623\u0631\u0627\u062f \u0627\u0644\u0644\u0647 \u0645\u0646\u0647 \u063a\u0627\u064a\u0629\u064e \u0627\u0644\u062a\u062d\u0642\u064a\u0642\u060c \u0648\u064a\u062a\u062d\u0631\u0631 \u0645\u0646 \u0627\u0644\u0648\u0647\u0645 \u0648\u0627\u0644\u062e\u0631\u0627\u0641\u0627\u062a.","\u0648\u0639\u0631\u064e\u0651\u0641 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u064e \u0628\u0646\u0641\u0633\u0647 \u0628\u0639\u062f \u0623\u0646 \u0639\u0631\u064e\u0651\u0641\u0647 \u0628\u0631\u0628\u0647 \u0648\u0628\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631\u060c \u0648\u0623\u062c\u0627\u0628 \u0639\u0644\u0649 \u062a\u0633\u0627\u0624\u0644\u0627\u062a \u0627\u0644\u0641\u0637\u0631\u0629: \u0645\u0646 \u0623\u064a\u0646\u061f \u0648\u0625\u0644\u0649 \u0623\u064a\u0646\u061f \u0648\u0647\u064a \u062a\u0633\u0627\u0624\u0644\u0627\u062a \u062a\u064e\u0641\u0631\u0650\u0636 \u0646\u0641\u0633\u0647\u0627 \u0639\u0644\u0649 \u0643\u0644 \u0625\u0646\u0633\u0627\u0646 \u0633\u0648\u064a \u0648\u062a\u064f\u0644\u0650\u062d\u064f\u0651 \u0641\u064a \u0637\u0644\u0628 \u0627\u0644\u062c\u0648\u0627\u0628\u060c \u0648\u0628\u064a\u064e\u0651\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u0644\u0644\u0635\u062d\u0627\u0628\u0629 \u0627\u0644\u0643\u0631\u0627\u0645 \u062d\u0642\u064a\u0642\u0629\u064e \u0646\u0634\u0623\u0629 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u064a\u0629 \u0648\u0623\u0635\u0648\u0644\u0647\u0645 \u0627\u0644\u062a\u064a \u064a\u0631\u062c\u0639\u0648\u0646 \u0625\u0644\u064a\u0647\u0627\u060c \u0648\u0645\u0627 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646\u0647\u0645 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u062d\u064a\u0627\u0629\u060c \u0648\u0645\u0627 \u0645\u0635\u064a\u0631\u0647\u0645 \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u062a."],t.s)
