B.aDd=s(["\u062b\u0645 \u062c\u0627\u0621\u062a \u0645\u0631\u062d\u0644\u0629\u064c \u0623\u062e\u0631\u0649\u060c \u0641\u0623\u0635\u0628\u062d \ufdfa \u064a\u062f\u0639\u0648 \u0643\u0644\u064e\u0651 \u0645\u064e\u0646 \u064a\u0644\u062a\u0642\u064a\u0647 \u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u0639\u0644\u0649 \u0627\u062e\u062a\u0644\u0627\u0641 \u0642\u0628\u0627\u0626\u0644\u0647\u0645 \u0648\u0628\u0644\u062f\u0627\u0646\u0647\u0645\u060c \u0648\u064a\u062a\u0628\u0639\u064f \u0627\u0644\u0646\u0627\u0633\u064e \u0641\u064a \u0623\u0646\u062f\u064a\u062a\u0647\u0645 \u0648\u0645\u062c\u0627\u0645\u0639\u0647\u0645 \u0648\u0645\u062d\u0627\u0641\u0644\u0647\u0645\u060c \u0648\u0641\u064a \u0627\u0644\u0645\u0648\u0627\u0633\u0645 \u0648\u0645\u0648\u0627\u0642\u0641 \u0627\u0644\u062d\u062c\u060c \u0648\u064a\u062f\u0639\u0648 \u0643\u0644 \u0645\u0646 \u064a\u0644\u0642\u0627\u0647 \u0645\u0646 \u062d\u0631\u064d\u0651 \u0648\u0639\u0628\u062f\u060c \u0648\u0642\u0648\u064a\u064d\u0651 \u0648\u0636\u0639\u064a\u0641\u060c \u0648\u063a\u0646\u064a\u064d\u0651 \u0648\u0641\u0642\u064a\u0631\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0641\u064e\u0627\u0635\u062f\u064e\u0639 \u0628\u0650\u0645\u064e\u0627 \u062a\u064f\u0624\u0645\u064e\u0631\u064f \u0648\u064e\u0623\u064e\u0639\u0631\u0650\u0636 \u0639\u064e\u0646\u0650 \u0627\u0644\u0645\u064f\u0634\u0631\u0650\u0643\u0650\u064a\u0646\u064e \u06dd \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064e\u0641\u064e\u064a\u0646\u064e\u0627\u0643\u064e \u0627\u0644\u0645\u064f\u0633\u062a\u064e\u0647\u0632\u0650\u0626\u0650\u064a\u0646\u064e \u06dd \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062c\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u0641\u064e\u0633\u064e\u0648\u0641\u064e \u064a\u064e\u0639\u0644\u064e\u0645\u064f\u0648\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u062d\u062c\u0631.","\u0643\u0627\u0646\u062a \u0627\u0644\u0646\u062a\u064a\u062c\u0629\u064f \u0644\u0647\u0630\u0627 \u0627\u0644\u0635\u064e\u0651\u062f\u0639 \u0647\u064a \u0627\u0644\u0635\u062f\u064e\u0651 \u0648\u0627\u0644\u0625\u0639\u0631\u0627\u0636 \u0648\u0627\u0644\u0633\u062e\u0631\u064a\u0629\u064e \u0648\u0627\u0644\u0625\u064a\u0630\u0627\u0621\u064e \u0648\u0627\u0644\u062a\u0643\u0630\u064a\u0628\u064e \u0648\u0627\u0644\u0643\u064a\u062f\u064e \u0627\u0644\u0645\u064f\u062f\u0628\u064e\u0651\u0631 \u0627\u0644\u0645\u062f\u0631\u0648\u0633\u060c \u0648\u0627\u0634\u062a\u062f\u064e\u0651 \u0627\u0644\u0635\u0631\u0627\u0639\u064f \u0628\u064a\u0646 \u0627\u0644\u0646\u0628\u064a\u0650\u0651 \ufdfa \u0648\u0635\u062d\u0628\u0647 \u0648\u0628\u064a\u0646 \u0634\u064a\u0648\u062e \u0627\u0644\u0648\u062b\u0646\u064a\u0629 \u0648\u0632\u0639\u0645\u0627\u0626\u0647\u0627\u060c \u0648\u0623\u0635\u0628\u062d \u0627\u0644\u0646\u0627\u0633\u064f \u0641\u064a \u0645\u0643\u0629 \u064a\u062a\u0646\u0627\u0642\u0644\u0648\u0646 \u0623\u062e\u0628\u0627\u0631 \u0630\u0644\u0643 \u0627\u0644\u0635\u0631\u0627\u0639 \u0641\u064a \u0643\u0644 \u0645\u0643\u0627\u0646\u060c \u0648\u0643\u0627\u0646 \u0647\u0630\u0627 \u0641\u064a \u062d\u062f \u0630\u0627\u062a\u0647 \u0645\u0643\u0633\u0628\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627 \u0644\u0644\u062f\u0639\u0648\u0629\u060c \u0633\u0627\u0647\u0645\u064e \u0641\u064a\u0647 \u0623\u0634\u062f\u064f\u0651 \u0623\u0639\u062f\u0627\u0626\u0647\u0627 \u0648\u0623\u064e\u0644\u064e\u062f\u064f\u0651\u0647\u0645\u060c \u0645\u0645\u0646 \u0643\u0627\u0646\u0648\u0627 \u064a\u064f\u0634\u064a\u0639\u0648\u0646 \u0641\u064a \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0642\u0627\u0644\u0629\u064e \u0627\u0644\u0633\u0648\u0621 \u0639\u0646\u0647\u0627\u060c \u0641\u0644\u064a\u0633 \u0643\u0644 \u0627\u0644\u0646\u0627\u0633 \u064a\u064f\u0633\u0644\u0650\u0651\u0645\u0648\u0646 \u0628\u062f\u0639\u0627\u0648\u0649 \u0632\u0639\u0645\u0627\u0621 \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0634\u0631\u0643\u060c \u0648\u0643\u0627\u0646\u062a \u0627\u0644\u0648\u0633\u064a\u0644\u0629\u064f \u0627\u0644\u0625\u0639\u0644\u0627\u0645\u064a\u0629 \u0641\u064a \u0630\u0644\u0643 \u0627\u0644\u0639\u0635\u0631 \u062a\u0646\u0627\u0642\u064f\u0644\u064e \u0627\u0644\u0646\u0627\u0633 \u0644\u0644\u0623\u062e\u0628\u0627\u0631 \u0645\u0634\u0627\u0641\u0647\u0629\u064b\u060c \u0641\u0633\u0645\u0639 \u0627\u0644\u0642\u0627\u0635\u064a \u0648\u0627\u0644\u062f\u0627\u0646\u064a \u0628\u0646\u0628\u0648\u0629 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa\u060c \u0648\u0635\u0627\u0631 \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u062b\u064f \u0627\u0644\u0639\u0638\u064a\u0645 \u062d\u062f\u064a\u062b\u064e \u0627\u0644\u0646\u0627\u0633 \u0641\u064a \u0627\u0644\u0645\u062c\u0627\u0644\u0633 \u0648\u0646\u0648\u0627\u062f\u064a \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0648\u0628\u064a\u0648\u062a \u0627\u0644\u0646\u0627\u0633."],t.s)
