B.aIK=s(["\u0643\u0627\u0646 \u0625\u0633\u0644\u0627\u0645 \u062e\u0627\u0644\u062f \u0644\u0631\u0624\u064a\u0627 \u0631\u0622\u0647\u0627 \u0639\u0646\u062f \u0623\u0648\u0644 \u0638\u0647\u0648\u0631 \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u0625\u0630 \u0631\u0623\u0649 \u0643\u0623\u0646\u0647 \u0648\u0642\u0641 \u0639\u0644\u0649 \u0634\u0641\u064a\u0631 \u0627\u0644\u0646\u0627\u0631 \u0648\u0647\u0646\u0627\u0643 \u0645\u0646 \u064a\u062f\u0641\u0639\u0647 \u0641\u064a\u0647\u0627\u060c \u0648\u0627\u0644\u0631\u0633\u0648\u0644 \u064a\u0644\u062a\u0632\u0645\u0647 \u0644\u0626\u0644\u0627 \u064a\u0642\u0639\u060c \u0641\u064e\u0641\u064e\u0632\u0650\u0639 \u0645\u0646 \u0646\u0648\u0645\u0647 \u0645\u0639\u062a\u0642\u062f\u064b\u0627 \u0623\u0646 \u0647\u0630\u0647 \u0627\u0644\u0631\u0624\u064a\u0627 \u062d\u0642\u060c \u0641\u0642\u0635\u064e\u0651\u0647\u0627 \u0639\u0644\u0649 \u0623\u0628\u064a \u0628\u0643\u0631 \u0627\u0644\u0635\u062f\u064a\u0642 \u0641\u0642\u0627\u0644 \u0644\u0647: \u0623\u064f\u0631\u064a\u062f \u0628\u0643 \u062e\u064a\u0631\u064b\u0627\u060c \u0647\u0630\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0627\u062a\u0628\u0639\u0647\u060c \u0641\u0630\u0647\u0628 \u0625\u0644\u064a\u0647 \u0641\u0623\u0633\u0644\u0645\u060c \u0648\u0623\u062e\u0641\u0649 \u0625\u0633\u0644\u0627\u0645\u0647 \u062e\u0648\u0641\u064b\u0627 \u0645\u0646 \u0623\u0628\u064a\u0647.","\u0644\u0643\u0646 \u0623\u0628\u0627\u0647 \u0639\u064e\u0644\u0650\u0645 \u0644\u0645\u0627 \u0631\u0623\u0649 \u0643\u062b\u0631\u0629 \u062a\u063a\u064a\u064f\u0651\u0628\u0647 \u0639\u0646\u0647\u060c \u0641\u0628\u0639\u062b \u0625\u062e\u0648\u062a\u0647 \u0627\u0644\u0630\u064a\u0646 \u0644\u0645 \u064a\u0643\u0648\u0646\u0648\u0627 \u0642\u062f \u0623\u0633\u0644\u0645\u0648\u0627 \u0628\u0639\u062f \u0641\u064a \u0637\u0644\u0628\u0647\u060c \u0641\u062c\u064a\u0621 \u0628\u0647 \u0641\u0623\u0646\u064e\u0651\u0628\u064e\u0647 \u0648\u0636\u0631\u0628\u0647 \u0628\u0645\u0650\u0642\u0631\u064e\u0639\u0629 \u0643\u0627\u0646\u062a \u0641\u064a \u064a\u062f\u0647 \u062d\u062a\u0649 \u0643\u0633\u0631\u0647\u0627 \u0639\u0644\u0649 \u0631\u0623\u0633\u0647\u060c \u062b\u0645 \u062d\u0628\u0633\u0647 \u0628\u0645\u0643\u0629 \u0648\u0645\u0646\u0639 \u0625\u062e\u0648\u062a\u0647 \u0645\u0646 \u0627\u0644\u0643\u0644\u0627\u0645 \u0645\u0639\u0647 \u0648\u062d\u0630\u064e\u0651\u0631\u0647\u0645 \u0645\u0646 \u0639\u0645\u0644\u0647\u060c \u062b\u0645 \u0636\u064a\u064e\u0651\u0642 \u0639\u0644\u064a\u0647 \u0627\u0644\u062e\u0646\u0627\u0642 \u0641\u0623\u062c\u0627\u0639\u0647 \u0648\u0642\u0637\u0639 \u0639\u0646\u0647 \u0627\u0644\u0645\u0627\u0621 \u062b\u0644\u0627\u062b\u0629 \u0623\u064a\u0627\u0645 \u0648\u0647\u0648 \u0635\u0627\u0628\u0631 \u0645\u062d\u062a\u0633\u0628\u060c \u062b\u0645 \u0642\u0627\u0644 \u0644\u0647 \u0623\u0628\u0648\u0647: \u0648\u0627\u0644\u0644\u0647 \u0644\u0623\u0645\u0646\u0639\u0646\u0643 \u0627\u0644\u0642\u0648\u062a\u060c \u0641\u0642\u0627\u0644 \u062e\u0627\u0644\u062f: \u0625\u0646 \u0645\u0646\u0639\u062a\u0646\u064a \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0631\u0632\u0642\u0646\u064a \u0645\u0627 \u0623\u0639\u064a\u0634 \u0628\u0647\u060c \u0648\u0627\u0646\u0635\u0631\u0641 \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0643\u0627\u0646 \u064a\u064f\u0643\u0631\u0645\u0647 \u0648\u064a\u0643\u0648\u0646 \u0645\u0639\u0647\u060c \u062b\u0645 \u0631\u0623\u0649 \u0623\u0646 \u064a\u0647\u0627\u062c\u0631 \u0625\u0644\u0649 \u0627\u0644\u062d\u0628\u0634\u0629 \u0645\u0639 \u0645\u0646 \u0647\u0627\u062c\u0631 \u0625\u0644\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u0627\u0644\u0645\u0631\u0629 \u0627\u0644\u062b\u0627\u0646\u064a\u0629."],t.s)
