B.aTx=s(["\u0627\u0644\u0627\u0628\u062a\u0644\u0627\u0621\u064f \u0633\u0646\u0629\u064f \u0627\u0644\u0644\u0647 \u0641\u064a \u062e\u0644\u0642\u0647\u060c \u0648\u0647\u0630\u0627 \u062c\u0644\u064a\u064c\u0651 \u0641\u064a \u062a\u0642\u0631\u064a\u0631\u0627\u062a \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645\u061b \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062c\u064e\u0639\u064e\u0644\u064e\u0643\u064f\u0645 \u062e\u064e\u0644\u064e\u0627\u0626\u0650\u0641\u064e \u0627\u0644\u0623\u064e\u0631\u0636\u0650 \u0648\u064e\u0631\u064e\u0641\u064e\u0639\u064e \u0628\u064e\u0639\u0636\u064e\u0643\u064f\u0645 \u0641\u064e\u0648\u0642\u064e \u0628\u064e\u0639\u0636\u064d \u062f\u064e\u0631\u064e\u062c\u064e\u0627\u062a\u064d \u0644\u0651\u0650\u064a\u064e\u0628\u0644\u064f\u0648\u064e\u0643\u064f\u0645 \u0641\u0650\u064a \u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0643\u064f\u0645 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0633\u064e\u0631\u0650\u064a\u0639\u064f \u0627\u0644\u0639\u0650\u0642\u064e\u0627\u0628\u0650 \u0648\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u0646\u0639\u0627\u0645\u060c \u0648\u0642\u0627\u0644 \u0633\u0628\u062d\u0627\u0646\u0647: \ufd3f\u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0646\u064e\u0627 \u0645\u064e\u0627 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0623\u064e\u0631\u0636\u0650 \u0632\u0650\u064a\u0646\u064e\u0629\u064b \u0644\u0651\u064e\u0647\u064e\u0627 \u0644\u0650\u0646\u064e\u0628\u0644\u064f\u0648\u064e\u0647\u064f\u0645 \u0623\u064e\u064a\u0651\u064f\u0647\u064f\u0645 \u0623\u064e\u062d\u0633\u064e\u0646\u064f \u0639\u064e\u0645\u064e\u0644\u064b\u0627\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0643\u0647\u0641\u060c \u0648\u0642\u0627\u0644 \u062c\u0644 \u0634\u0623\u0646\u0647: \ufd3f\u0625\u0650\u0646\u0651\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u0646\u064e\u0627 \u0627\u0644\u0625\u0650\u0646\u0633\u064e\u0627\u0646\u064e \u0645\u0650\u0646 \u0646\u0651\u064f\u0637\u0641\u064e\u0629\u064d \u0623\u064e\u0645\u0634\u064e\u0627\u062c\u064d \u0646\u0651\u064e\u0628\u062a\u064e\u0644\u0650\u064a\u0647\u0650 \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u0646\u064e\u0627\u0647\u064f \u0633\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u0628\u064e\u0635\u0650\u064a\u0631\u064b\u0627\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0625\u0646\u0633\u0627\u0646.","\u0648\u0627\u0644\u0627\u0628\u062a\u0644\u0627\u0621\u064f \u0645\u0631\u062a\u0628\u0637\u064c \u0628\u0627\u0644\u062a\u0645\u0643\u064a\u0646 \u0627\u0631\u062a\u0628\u0627\u0637\u0627\u064b \u0648\u062b\u064a\u0642\u0627\u064b\u061b \u0641\u0642\u062f \u062c\u0631\u062a \u0633\u0646\u0629\u064f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0623\u0644\u0627 \u064a\u064f\u0645\u0643\u0650\u0651\u0646 \u0644\u0623\u0645\u0629\u064d \u0625\u0644\u0627 \u0628\u0639\u062f \u0623\u0646 \u062a\u0645\u0631\u064e\u0651 \u0628\u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u0629\u060c \u0648\u0628\u0639\u062f \u0623\u0646 \u064a\u064e\u0646\u0635\u0647\u0631 \u0645\u0639\u062f\u0646\u064f\u0647\u0627 \u0641\u064a \u0628\u0648\u062a\u0642\u0629 \u0627\u0644\u0623\u062d\u062f\u0627\u062b\u060c \u0641\u064a\u0645\u064a\u0632\u064e \u0627\u0644\u0644\u0647\u064f \u0627\u0644\u062e\u0628\u064a\u062b\u064e \u0645\u0646 \u0627\u0644\u0637\u064a\u0628\u060c \u0648\u0647\u064a \u0633\u0646\u0629\u064c \u062c\u0627\u0631\u064a\u0629\u064c \u0639\u0644\u0649 \u0627\u0644\u0623\u0645\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a\u0629 \u0644\u0627 \u062a\u062a\u062e\u0644\u0641\u060c \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0628\u0647\u0627 \u0623\u0646 \u064a\u0628\u062a\u0644\u064a \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u064a\u062e\u062a\u0628\u0631\u0647\u0645 \u0648\u0644\u064a\u0645\u062d\u0635\u064e \u0625\u064a\u0645\u0627\u0646\u0647\u0645\u060c \u062b\u0645 \u064a\u0643\u0648\u0646 \u0644\u0647\u0645 \u0627\u0644\u062a\u0645\u0643\u064a\u0646\u064f \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0628\u0639\u062f \u0630\u0644\u0643\u060c \u0648\u0644\u0630\u0644\u0643 \u062c\u0627\u0621 \u0647\u0630\u0627 \u0627\u0644\u0645\u0639\u0646\u0649 \u0639\u0644\u0649 \u0644\u0633\u0627\u0646 \u0627\u0644\u0625\u0645\u0627\u0645 \u0627\u0644\u0634\u0627\u0641\u0639\u064a \u0631\u062d\u0645\u0647 \u0627\u0644\u0644\u0647 \u062d\u064a\u0646 \u0633\u0623\u0644\u0647 \u0631\u062c\u0644: \u0623\u064a\u0647\u0645\u0627 \u0623\u0641\u0636\u0644 \u0644\u0644\u0645\u0631\u0621\u060c \u0623\u0646 \u064a\u064f\u0645\u0643\u064e\u0651\u0646 \u0623\u0648 \u064a\u064f\u0628\u062a\u0644\u0649\u061f \u0641\u0642\u0627\u0644: \u0644\u0627 \u064a\u064f\u0645\u0643\u064e\u0651\u0646 \u062d\u062a\u0649 \u064a\u064f\u0628\u062a\u0644\u0649\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0628\u062a\u0644\u0649 \u0646\u0648\u062d\u0627\u064b \u0648\u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0645\u0648\u0633\u0649 \u0648\u0639\u064a\u0633\u0649 \u0648\u0645\u062d\u0645\u062f\u0627\u064b \u0635\u0644\u0648\u0627\u062a \u0627\u0644\u0644\u0647 \u0648\u0633\u0644\u0627\u0645\u0647 \u0639\u0644\u064a\u0647\u0645 \u0623\u062c\u0645\u0639\u064a\u0646\u060c \u0641\u0644\u0645\u0627 \u0635\u0628\u0631\u0648\u0627 \u0645\u0643\u064e\u0651\u0646\u0647\u0645\u060c \u0641\u0644\u0627 \u064a\u0638\u0646\u064e\u0651\u0646 \u0623\u062d\u062f\u064c \u0623\u0646 \u064a\u062e\u0644\u0635 \u0645\u0646 \u0627\u0644\u0623\u0644\u0645 \u0627\u0644\u0628\u062a\u0629."],t.s)
