B.aDG=s(["\u0625\u0646 \u062a\u0633\u0645\u064a\u0629 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0642\u0628\u0644 \u0627\u0644\u0623\u0643\u0644 \u062a\u0637\u0628\u064a\u0642\u064c \u0644\u0633\u0646\u064e\u0651\u0629 \u0645\u0646 \u0633\u064f\u0646\u064e\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0627\u0644\u0638\u0627\u0647\u0631\u0629\u060c \u0648\u0642\u062f \u0643\u0627\u0646 \u0645\u0646 \u0628\u0631\u0643\u0629 \u0630\u0644\u0643 \u0627\u0646\u062c\u0630\u0627\u0628\u064f \u0639\u062f\u064e\u0651\u0627\u0633 \u0627\u0644\u0646\u0635\u0631\u0627\u0646\u064a \u0625\u0644\u064a\u0647\u060c \u0641\u0645\u0627 \u0623\u0646 \u0630\u0643\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0633\u0645 \u0627\u0644\u0644\u0647 \u0642\u0628\u0644 \u0627\u0644\u0623\u0643\u0644 \u062d\u062a\u0649 \u0627\u0647\u062a\u0632\u064e\u0651 \u0643\u064a\u0627\u0646\u064f \u0630\u0644\u0643 \u0627\u0644\u063a\u0644\u0627\u0645\u060c \u0648\u062c\u0627\u0634\u064e\u062a \u0645\u0634\u0627\u0639\u0631\u0647\u060c \u0641\u0623\u062e\u0628\u0631 \u0627\u0644\u0646\u0628\u064a\u064e\u0651 \ufdfa \u0628\u0639\u062c\u0628\u0647\u060c \u0625\u0630 \u0644\u0627 \u064a\u0639\u0631\u0641 \u0623\u0647\u0644 \u062a\u0644\u0643 \u0627\u0644\u0628\u0644\u0627\u062f \u0630\u0650\u0643\u0631\u064e \u0627\u0633\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u062a\u0633\u0645\u064a\u0629 \u0643\u0633\u0627\u0626\u0631 \u0627\u0644\u0633\u0646\u0646 \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0645\u0646 \u0623\u0633\u0628\u0627\u0628 \u062a\u0645\u064a\u064f\u0651\u0632 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0639\u0644\u0649 \u0645\u0646 \u062d\u0648\u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u0648\u062b\u0646\u064a\u064a\u0646\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u062a\u0645\u064a\u064f\u0651\u0632 \u064a\u0644\u0641\u062a \u0623\u0646\u0638\u0627\u0631 \u0627\u0644\u0643\u0641\u0627\u0631 \u0648\u064a\u062f\u0641\u0639\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0633\u0624\u0627\u0644 \u0639\u0646 \u0633\u0628\u0628\u0647\u060c \u062b\u0645 \u064a\u0642\u0648\u062f\u0647\u0645 \u0625\u0644\u0649 \u0641\u0647\u0645 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0627\u0644\u0627\u0646\u062c\u0630\u0627\u0628 \u0625\u0644\u064a\u0647.","\u0648\u0643\u0627\u0646 \u064a\u0642\u064a\u0646\u064f \u0639\u062f\u064e\u0651\u0627\u0633 \u0628\u0646\u0628\u0648\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u0642\u064a\u0646\u064b\u0627 \u0631\u0627\u0633\u062e\u064b\u0627\u060c \u064a\u062f\u0644\u064f\u0651 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0645\u0648\u0642\u0641\u064f\u0647 \u0645\u0646 \u0633\u064a\u0650\u0651\u062f\u064a\u0647 \u0639\u062a\u0628\u0629 \u0648\u0634\u064a\u0628\u0629 \u0627\u0628\u0646\u064e\u064a \u0631\u0628\u064a\u0639\u0629 \u0644\u0645\u064e\u0651\u0627 \u0623\u0631\u0627\u062f\u0627 \u0627\u0644\u062e\u0631\u0648\u062c \u0625\u0644\u0649 \u0628\u062f\u0631 \u0648\u0623\u0645\u0631\u0627\u0647 \u0628\u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0639\u0647\u0645\u0627\u060c \u0641\u0642\u0627\u0644 \u0644\u0647\u0645\u0627: \u0642\u062a\u0627\u0644\u064e \u0630\u0644\u0643 \u0627\u0644\u0631\u062c\u0644 \u0627\u0644\u0630\u064a \u0631\u0623\u064a\u062a\u064f\u0645\u0627 \u0641\u064a \u062d\u0627\u0626\u0637\u0643\u0645\u0627 \u062a\u064f\u0631\u064a\u062f\u0627\u0646\u061f \u0641\u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u062a\u0642\u0648\u0645 \u0644\u0647 \u0627\u0644\u062c\u0628\u0627\u0644\u060c \u0641\u0642\u0627\u0644 \u0623\u062d\u062f\u0647\u0645\u0627: \u0648\u064a\u062d\u0643 \u064a\u0627 \u0639\u062f\u064e\u0651\u0627\u0633\u060c \u0642\u062f \u0633\u062d\u0631\u0643 \u0628\u0644\u0633\u0627\u0646\u0647.","\u0648\u0641\u064a \u0642\u0648\u0644 \u0639\u062f\u064e\u0651\u0627\u0633: \u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0634\u064a\u0621 \u062e\u064a\u0631\u064c \u0645\u0646 \u0647\u0630\u0627\u060c \u0645\u0648\u0627\u0633\u0627\u0629\u064c \u0639\u0638\u064a\u0645\u0629 \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0641\u0644\u0626\u0646 \u0622\u0630\u0627\u0647 \u0642\u0648\u0645\u064f\u0647 \u0648\u0631\u062f\u064e\u0651\u0647 \u0623\u0647\u0644 \u0627\u0644\u0637\u0627\u0626\u0641\u060c \u0641\u0647\u0630\u0627 \u0648\u0627\u0641\u062f\u064c \u0645\u0646 \u0627\u0644\u0639\u0631\u0627\u0642\u060c \u0645\u0646 \u0646\u064a\u0646\u0648\u0649\u060c \u064a\u064f\u0643\u0650\u0628\u064f\u0651 \u0639\u0644\u0649 \u064a\u062f\u064a\u0647 \u0648\u0631\u062c\u0644\u064a\u0647 \u0648\u064a\u064f\u0642\u0628\u0650\u0651\u0644\u0647\u0645\u0627\u060c \u0648\u064a\u0634\u0647\u062f \u0644\u0647 \u0628\u0627\u0644\u0631\u0633\u0627\u0644\u0629\u060c \u0648\u0625\u0646 \u0641\u064a \u0630\u0644\u0643 \u0644\u0642\u064e\u062f\u064e\u0631\u064b\u0627 \u0631\u0628\u0627\u0646\u064a\u064b\u0651\u0627\u060c \u064a\u0633\u0648\u0642 \u0645\u0646 \u0646\u064a\u0646\u0648\u0649 \u0645\u0646 \u064a\u064f\u0624\u0645\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u062d\u064a\u062b \u0643\u0627\u0646 \u0627\u0644\u0635\u062f\u064f\u0651 \u0645\u0646 \u0623\u0642\u0631\u0628 \u0627\u0644\u0646\u0627\u0633 \u0625\u0644\u064a\u0647."],t.s)
