B.ay6=s(["\u0648\u0645\u0646 \u0623\u0633\u0627\u0644\u064a\u0628 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0641\u064a \u0627\u0644\u0631\u062f \u0639\u0644\u0649 \u0645\u0643\u0627\u0626\u062f \u0623\u0628\u064a \u062c\u0647\u0644 \u0648\u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0637\u0648\u0627\u0641 \u0639\u0644\u0649 \u0627\u0644\u0642\u0628\u0627\u0626\u0644: ","- \u0645\u0642\u0627\u0628\u0644\u0629 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0641\u064a \u0627\u0644\u0644\u064a\u0644: \u0645\u0646 \u062d\u0643\u0645\u062a\u0647 \ufdfa \u0627\u0644\u0639\u0627\u0644\u064a\u0629 \u0623\u0646\u0647 \u0643\u0627\u0646 \u064a\u062e\u0631\u062c \u0644\u0645\u0642\u0627\u0628\u0644\u0629 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0641\u064a \u0638\u0644\u0627\u0645 \u0627\u0644\u0644\u064a\u0644\u060c \u062d\u062a\u0649 \u0644\u0627 \u064a\u064e\u062d\u0648\u0644 \u0628\u064a\u0646\u0647 \u0648\u0628\u064a\u0646\u0647\u0645 \u0623\u062d\u062f\u064c \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u060c \u0648\u0642\u062f \u0646\u062c\u062d \u0647\u0630\u0627 \u0627\u0644\u0639\u0645\u0644 \u0641\u064a \u0625\u0628\u0637\u0627\u0644 \u0645\u0641\u0639\u0648\u0644 \u0627\u0644\u062f\u0639\u0627\u064a\u0629 \u0627\u0644\u0645\u0636\u0627\u062f\u0629 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u062a\u062a\u0628\u0639\u0647\u0627 \u0642\u0631\u064a\u0634 \u0643\u0644\u0645\u0627 \u0627\u062a\u0635\u0644 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0628\u0642\u0628\u064a\u0644\u0629 \u0645\u0646 \u0627\u0644\u0642\u0628\u0627\u0626\u0644\u060c \u0648\u0627\u0644\u062f\u0644\u064a\u0644\u064f \u0639\u0644\u0649 \u0646\u062c\u0627\u062d \u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0644\u0648\u0628 \u0623\u0646 \u0627\u062a\u0635\u0627\u0644\u0647 \ufdfa \u0628\u0627\u0644\u0623\u0648\u0633 \u0648\u0627\u0644\u062e\u0632\u0631\u062c \u0643\u0627\u0646 \u0644\u064a\u0644\u0627\u064b\u060c \u0648\u0645\u0646 \u062b\u064e\u0645\u064e\u0651 \u0643\u0627\u0646\u062a \u0628\u064a\u0639\u0629 \u0627\u0644\u0639\u0642\u0628\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0644\u064a\u0644\u0627\u064b.","- \u0627\u0635\u0637\u062d\u0627\u0628 \u0627\u0644\u0623\u0639\u0648\u0627\u0646: \u0648\u0643\u0627\u0646 \ufdfa \u064a\u0623\u062a\u064a \u0627\u0644\u0642\u0628\u0627\u0626\u0644\u064e \u0641\u064a \u0645\u0646\u0627\u0632\u0644\u0647\u0645\u060c \u0641\u0623\u062a\u0649 \u0643\u0644\u0628\u064b\u0627 \u0648\u0628\u0646\u064a \u062d\u0646\u064a\u0641\u0629 \u0648\u0628\u0646\u064a \u0639\u0627\u0645\u0631 \u0641\u064a \u062f\u064a\u0627\u0631\u0647\u0645\u060c \u0648\u0628\u0630\u0644\u0643 \u0627\u0628\u062a\u0639\u062f \u0639\u0646 \u0645\u0637\u0627\u0631\u062f\u0629 \u0642\u0631\u064a\u0634\u060c \u0648\u0627\u0633\u062a\u0637\u0627\u0639 \u0623\u0646 \u064a\u062a\u0641\u0627\u0648\u0636 \u0645\u0639 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u062f\u0648\u0646\u0645\u0627 \u062a\u0634\u0648\u064a\u0634 \u0623\u0648 \u062a\u0634\u0648\u064a\u0647. \u0648\u0643\u0627\u0646 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0648\u0639\u0644\u064a \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627 \u064a\u064f\u0631\u0627\u0641\u0642\u0627\u0646\u0647 \ufdfa \u0641\u064a \u0628\u0639\u0636 \u0647\u0630\u0647 \u0627\u0644\u0645\u0641\u0627\u0648\u0636\u0627\u062a\u060c \u0644\u0626\u0644\u0627 \u064a\u0638\u0646 \u0627\u0644\u0645\u062f\u0639\u0648\u064f\u0651\u0648\u0646 \u0623\u0646\u0647 \u0648\u062d\u064a\u062f \u0644\u0627 \u0623\u0639\u0648\u0627\u0646 \u0644\u0647 \u0645\u0646 \u0623\u0634\u0631\u0627\u0641 \u0642\u0648\u0645\u0647 \u0648\u0623\u0642\u0627\u0631\u0628\u0647\u060c \u0647\u0630\u0627 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0645\u0627 \u0644\u0623\u0628\u064a \u0628\u0643\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0645\u0646 \u0645\u0639\u0631\u0641\u0629 \u0628\u0623\u0646\u0633\u0627\u0628 \u0627\u0644\u0639\u0631\u0628\u060c \u0645\u0645\u0627 \u064a\u064f\u0639\u064a\u0646 \u0627\u0644\u0631\u0633\u0648\u0644\u064e \ufdfa \u0639\u0644\u0649 \u0627\u0644\u062a\u0639\u0631\u0641 \u0639\u0644\u0649 \u0645\u0639\u0627\u062f\u0646 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0641\u064a\u064e\u0642\u0639 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631 \u0639\u0644\u0649 \u0623\u0641\u0636\u0644\u0647\u0627 \u0644\u062a\u062d\u0645\u064f\u0651\u0644 \u062a\u064e\u0628\u0650\u0639\u0627\u062a \u0627\u0644\u062f\u0639\u0648\u0629.","- \u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0642\u0628\u064a\u0644\u0629: \u0648\u0630\u0644\u0643 \u0645\u0646 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u0623\u0645\u0646\u064a\u0629 \u0627\u0644\u0645\u0647\u0645\u0629 \u064a\u0643\u0648\u0646 \u0633\u0624\u0627\u0644\u064f\u0647 \ufdfa \u0639\u0646 \u0627\u0644\u0642\u0648\u0629 \u0648\u0627\u0644\u0645\u0646\u0639\u0629 \u0644\u062f\u0649 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0648\u062c\u0647 \u0625\u0644\u064a\u0647\u0645 \u0627\u0644\u062f\u0639\u0648\u0629\u064e \u0648\u064a\u0637\u0644\u0628 \u0645\u0646\u0647\u0645 \u0627\u0644\u062d\u0645\u0627\u064a\u0629\u060c \u0625\u0630 \u0625\u0646 \u0627\u0644\u0642\u0628\u064a\u0644\u0629\u064e \u0627\u0644\u062a\u064a \u062a\u064e\u062d\u0645\u064a \u0627\u0644\u062f\u0639\u0648\u0629\u064e \u0633\u062a\u0648\u0627\u062c\u0647 \u0643\u0644\u064e\u0651 \u0642\u0648\u0649 \u0627\u0644\u0634\u0631 \u0648\u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0641\u0644\u0627 \u0628\u062f \u0623\u0646 \u062a\u0643\u0648\u0646 \u0623\u0647\u0644\u0627\u064b \u0644\u0647\u0630\u0627 \u0627\u0644\u062f\u0648\u0631 \u0645\u0646 \u062d\u064a\u062b \u0627\u0644\u0627\u0633\u062a\u0639\u062f\u0627\u062f \u0627\u0644\u0645\u0639\u0646\u0648\u064a \u0648\u0627\u0644\u0645\u0627\u062f\u064a\u060c \u0627\u0644\u0630\u064a \u064a\u064f\u0631\u0647\u0650\u0628 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0648\u064a\u064e\u062d\u0645\u064a \u062d\u0645\u0649 \u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0648\u064a\u062a\u062d\u0645\u0644 \u062a\u0628\u0639\u0627\u062a \u0646\u0634\u0631\u0647\u0627 \u0645\u0632\u064a\u0644\u0627\u064b \u0643\u0644 \u0627\u0644\u0639\u0642\u0628\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u0642\u0641 \u0641\u064a \u0637\u0631\u064a\u0642\u0647\u0627."],t.s)
