B.aSy=s(["\u0641\u064a \u0631\u0648\u0627\u064a\u0629 \u064a\u0631\u0648\u064a\u0647\u0627 \u0639\u0644\u064a\u064c\u0651 \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0641\u064a\u0642\u0648\u0644: \u0644\u0645\u0627 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0646\u0628\u064a\u0647 \ufdfa \u0623\u0646 \u064a\u0639\u0631\u0636 \u0646\u0641\u0633\u0647 \u0639\u0644\u0649 \u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u0639\u0631\u0628 \u062e\u0631\u062c \u0648\u0623\u0646\u0627 \u0645\u0639\u0647\u060c \u062d\u062a\u0649 \u0627\u0646\u062a\u0647\u064a\u0646\u0627 \u0625\u0644\u0649 \u0645\u062c\u0644\u0633 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0643\u064a\u0646\u0629 \u0648\u0627\u0644\u0648\u0642\u0627\u0631\u060c \u0641\u062a\u0642\u062f\u064e\u0651\u0645 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0641\u0633\u0644\u064e\u0651\u0645 \u0648\u0642\u0627\u0644: \u0645\u0646 \u0627\u0644\u0642\u0648\u0645\u061f \u0642\u0627\u0644\u0648\u0627: \u0634\u064a\u0628\u0627\u0646 \u0628\u0646 \u062b\u0639\u0644\u0628\u0629\u060c \u0641\u0627\u0644\u062a\u0641\u062a \u0623\u0628\u0648 \u0628\u0643\u0631 \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0642\u0627\u0644: \u0628\u0623\u0628\u064a \u0648\u0623\u0645\u064a\u060c \u0647\u0624\u0644\u0627\u0621 \u063a\u064f\u0631\u064e\u0631 \u0627\u0644\u0646\u0627\u0633\u060c \u0648\u0641\u064a\u0647\u0645 \u0645\u0641\u0631\u0648\u0642 \u0642\u062f \u063a\u0644\u0628\u0647\u0645 \u0644\u0633\u0627\u0646\u064b\u0627 \u0648\u062c\u0645\u0627\u0644\u0627\u064b\u060c \u0648\u0643\u0627\u0646\u062a \u0644\u0647 \u063a\u062f\u064a\u0631\u062a\u0627\u0646 \u062a\u0633\u0642\u0637\u0627\u0646 \u0639\u0644\u0649 \u062a\u0631\u064a\u0628\u062a\u064a\u0647\u060c \u0648\u0643\u0627\u0646 \u0623\u062f\u0646\u0649 \u0627\u0644\u0642\u0648\u0645 \u0645\u062c\u0644\u0633\u064b\u0627 \u0645\u0646 \u0623\u0628\u064a \u0628\u0643\u0631\u060c \u0641\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631: \u0643\u064a\u0641 \u0627\u0644\u0639\u062f\u062f \u0641\u064a\u0643\u0645\u061f \u0641\u0642\u0627\u0644 \u0645\u0641\u0631\u0648\u0642: \u0625\u0646\u0627 \u0644\u0627 \u0646\u0632\u064a\u062f \u0639\u0644\u0649 \u0627\u0644\u0623\u0644\u0641\u060c \u0648\u0644\u0646 \u062a\u064f\u063a\u0644\u0628 \u0623\u0644\u0641 \u0645\u0646 \u0642\u0644\u0629\u060c \u0641\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631: \u0648\u0643\u064a\u0641 \u0627\u0644\u0645\u0646\u0639\u0629 \u0641\u064a\u0643\u0645\u061f \u0641\u0642\u0627\u0644 \u0645\u0641\u0631\u0648\u0642: \u0625\u0646\u0627 \u0644\u0623\u0634\u062f \u0645\u0627 \u0646\u0643\u0648\u0646 \u063a\u0636\u0628\u064b\u0627 \u062d\u064a\u0646 \u0646\u0644\u0642\u0649\u060c \u0648\u0623\u0634\u062f \u0645\u0627 \u0646\u0643\u0648\u0646 \u0644\u0642\u0627\u0621\u064b \u062d\u064a\u0646 \u0646\u063a\u0636\u0628\u060c \u0648\u0625\u0646\u0627 \u0644\u0646\u064f\u0624\u062b\u0631 \u0627\u0644\u062c\u064a\u0627\u062f \u0639\u0644\u0649 \u0627\u0644\u0623\u0648\u0644\u0627\u062f\u060c \u0648\u0627\u0644\u0633\u0644\u0627\u062d \u0639\u0644\u0649 \u0627\u0644\u0644\u0650\u0651\u0642\u0627\u062d\u060c \u0648\u0627\u0644\u0646\u0635\u0631 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u064a\u064f\u062f\u064a\u0644\u0646\u0627 \u0645\u0631\u0629 \u0648\u064a\u064f\u062f\u064a\u0644 \u0639\u0644\u064a\u0646\u0627 \u0623\u062e\u0631\u0649\u060c \u0644\u0639\u0644\u0643 \u0623\u062e\u0648 \u0642\u0631\u064a\u0634\u061f \u0641\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631: \u0625\u0646 \u0643\u0627\u0646 \u0628\u0644\u063a\u0643\u0645 \u0623\u0646\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0647\u0627 \u0647\u0648 \u0630\u0627\u060c \u0641\u0642\u0627\u0644 \u0645\u0641\u0631\u0648\u0642: \u0625\u0644\u0627\u0645 \u062a\u062f\u0639\u0648\u0646\u0627 \u064a\u0627 \u0623\u062e\u0627 \u0642\u0631\u064a\u0634\u061f","\u0627\u0644\u0645\u0639\u0627\u0646\u064a: [ \u063a\u064f\u0631\u064e\u0631: \u0633\u0627\u062f\u0627\u062a \u0627\u0644\u0642\u0648\u0645 \u0648\u0623\u0634\u0631\u0627\u0641\u0647\u0645 | \u0645\u0641\u0631\u0648\u0642: \u0623\u062d\u062f \u0633\u0627\u062f\u0629 \u0628\u0646\u064a \u0634\u064a\u0628\u0627\u0646 \u0627\u0644\u0648\u0627\u0641\u062f\u064a\u0646 | \u063a\u062f\u064a\u0631\u062a\u0627\u0646: \u0636\u0641\u064a\u0631\u062a\u0627\u0646 \u0645\u0646 \u0627\u0644\u0634\u0639\u0631 | \u062a\u0631\u064a\u0628\u062a\u064a\u0647: \u0623\u0639\u0644\u0649 \u0635\u062f\u0631\u0647 | \u0627\u0644\u0644\u0650\u0651\u0642\u0627\u062d: \u0627\u0644\u0646\u0648\u0642 \u0630\u0648\u0627\u062a \u0627\u0644\u062d\u0644\u064a\u0628 ].","\u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \xab\u0623\u062f\u0639\u0648\u0643\u0645 \u0625\u0644\u0649 \u0634\u0647\u0627\u062f\u0629 \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647\u060c \u0648\u0623\u0646\u064a \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0625\u0644\u0649 \u0623\u0646 \u062a\u0624\u0648\u0648\u0646\u064a \u0648\u062a\u0646\u0635\u0631\u0648\u0646\u064a\u060c \u0641\u0625\u0646 \u0642\u0631\u064a\u0634\u064b\u0627 \u0642\u062f \u062a\u0638\u0627\u0647\u0631\u062a \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0643\u0630\u064e\u0651\u0628\u062a \u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0627\u0633\u062a\u063a\u0646\u062a \u0628\u0627\u0644\u0628\u0627\u0637\u0644 \u0639\u0646 \u0627\u0644\u062d\u0642\u060c \u0648\u0627\u0644\u0644\u0647 \u0647\u0648 \u0627\u0644\u063a\u0646\u064a \u0627\u0644\u062d\u0645\u064a\u062f\xbb\u060c \u0641\u0642\u0627\u0644 \u0645\u0641\u0631\u0648\u0642: \u0648\u0625\u0644\u0627\u0645 \u062a\u062f\u0639\u0648 \u0623\u064a\u0636\u064b\u0627 \u064a\u0627 \u0623\u062e\u0627 \u0642\u0631\u064a\u0634\u061f \u0641\u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0633\u0645\u0639\u062a \u0643\u0644\u0627\u0645\u064b\u0627 \u0623\u062d\u0633\u0646 \u0645\u0646 \u0647\u0630\u0627\u060c \u0641\u062a\u0644\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \ufd3f\u0642\u064f\u0644 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0648\u0627 \u0623\u064e\u062a\u0644\u064f \u0645\u064e\u0627 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064f\u0645 \u0639\u064e\u0644\u064e\u064a\u0643\u064f\u0645 \u0623\u064e\u0644\u0651\u064e\u0627 \u062a\u064f\u0634\u0631\u0650\u0643\u064f\u0648\u0627 \u0628\u0650\u0647\u0650 \u0634\u064e\u064a\u0626\u064b\u0627 \u0648\u064e\u0628\u0650\u0627\u0644\u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0646\u0650 \u0625\u0650\u062d\u0633\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u062a\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0648\u0644\u064e\u0627\u062f\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0625\u0650\u0645\u0644\u064e\u0627\u0642\u064d \u0646\u0651\u064e\u062d\u0646\u064f \u0646\u064e\u0631\u0632\u064f\u0642\u064f\u0643\u064f\u0645 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0647\u064f\u0645 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u0631\u064e\u0628\u064f\u0648\u0627 \u0627\u0644\u0641\u064e\u0648\u064e\u0627\u062d\u0650\u0634\u064e \u0645\u064e\u0627 \u0638\u064e\u0647\u064e\u0631\u064e \u0645\u0650\u0646\u0647\u064e\u0627 \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u0637\u064e\u0646\u064e \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0642\u062a\u064f\u0644\u064f\u0648\u0627 \u0627\u0644\u0646\u0651\u064e\u0641\u0633\u064e \u0627\u0644\u0651\u064e\u062a\u0650\u064a \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0627\u0644\u062d\u064e\u0642\u0651\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0648\u064e\u0635\u0651\u064e\u0627\u0643\u064f\u0645 \u0628\u0650\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645 \u062a\u064e\u0639\u0642\u0650\u0644\u064f\u0648\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u0646\u0639\u0627\u0645.","\u0641\u0642\u0627\u0644 \u0645\u0641\u0631\u0648\u0642: \u062f\u0639\u0648\u062a\u064e \u0648\u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u0645\u0643\u0627\u0631\u0645 \u0627\u0644\u0623\u062e\u0644\u0627\u0642 \u0648\u0645\u062d\u0627\u0633\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644\u060c \u0648\u0644\u0642\u062f \u0623\u064e\u0641\u064e\u0643\u064e \u0642\u0648\u0645\u064c \u0643\u0630\u064e\u0651\u0628\u0648\u0643 \u0648\u0638\u0627\u0647\u0631\u0648\u0627 \u0639\u0644\u064a\u0643\u060c \u062b\u0645 \u0631\u062f\u064e\u0651 \u0627\u0644\u0623\u0645\u0631 \u0625\u0644\u0649 \u0647\u0627\u0646\u0626 \u0628\u0646 \u0642\u0628\u064a\u0635\u0629\u060c \u0641\u0642\u0627\u0644: \u0648\u0647\u0630\u0627 \u0647\u0627\u0646\u0626 \u0634\u064a\u062e\u0646\u0627 \u0648\u0635\u0627\u062d\u0628 \u062f\u064a\u0646\u0646\u0627\u060c \u0641\u0642\u0627\u0644 \u0647\u0627\u0646\u0626: \u0642\u062f \u0633\u0645\u0639\u062a \u0645\u0642\u0627\u0644\u062a\u0643 \u064a\u0627 \u0623\u062e\u0627 \u0642\u0631\u064a\u0634\u060c \u0648\u0625\u0646\u064a \u0623\u0631\u0649 \u062a\u0631\u0643\u0646\u0627 \u062f\u064a\u0646\u0646\u0627 \u0648\u0627\u062a\u0628\u0627\u0639\u0646\u0627 \u062f\u064a\u0646\u0643 \u0644\u0645\u062c\u0644\u0633 \u062c\u0644\u0633\u062a\u0647 \u0625\u0644\u064a\u0646\u0627 \u0644\u0627 \u0623\u0648\u0644 \u0644\u0647 \u0648\u0644\u0627 \u0622\u062e\u0631\u060c \u0632\u064e\u0644\u064e\u0651\u0629\u064c \u0641\u064a \u0627\u0644\u0631\u0623\u064a \u0648\u0642\u0650\u0644\u064e\u0651\u0629 \u0646\u0638\u0631 \u0641\u064a \u0627\u0644\u0639\u0627\u0642\u0628\u0629\u060c \u0648\u0625\u0646 \u0627\u0644\u0632\u0644\u0629 \u0645\u0639 \u0627\u0644\u0639\u062c\u0644\u0629\u060c \u0648\u0625\u0646\u0627 \u0646\u0643\u0631\u0647 \u0623\u0646 \u0646\u0639\u0642\u062f \u0639\u0644\u0649 \u0645\u0646 \u0648\u0631\u0627\u0621\u0646\u0627 \u0639\u064e\u0642\u062f\u064b\u0627\u060c \u0648\u0644\u0643\u0646 \u0646\u0631\u062c\u0639 \u0648\u062a\u0631\u062c\u0639 \u0648\u0646\u0646\u0638\u0631.","\u0627\u0644\u0645\u0639\u0627\u0646\u064a: [ \u0623\u064e\u0641\u064e\u0643\u064e \u0642\u0648\u0645\u064c: \u0643\u0630\u064e\u0628\u064e \u0648\u0636\u0644\u064e\u0651 \u0642\u0648\u0645\u064c \u0639\u0646 \u0627\u0644\u062d\u0642 (\u0645\u0646 \u0627\u0644\u0625\u0641\u0643\u060c \u0648\u0647\u0648 \u0623\u0633\u0648\u0623 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0643\u0630\u0628) | \u0632\u064e\u0644\u064e\u0651\u0629\u064c \u0641\u064a \u0627\u0644\u0631\u0623\u064a: \u062e\u0637\u0623 \u0623\u0648 \u0647\u0641\u0648\u0629 \u0641\u064a \u0627\u0644\u0642\u0631\u0627\u0631 \u0646\u0627\u062a\u062c\u0629 \u0639\u0646 \u0627\u0644\u062a\u0633\u0631\u064f\u0651\u0639 \u0648\u0639\u062f\u0645 \u0627\u0644\u062a\u0631\u0648\u0650\u0651\u064a ].","\u062b\u0645 \u0643\u0623\u0646\u0647 \u0623\u062d\u0628 \u0623\u0646 \u064a\u064f\u0634\u0631\u0643\u0647 \u0627\u0644\u0645\u062b\u0646\u0649 \u0628\u0646 \u062d\u0627\u0631\u062b\u0629 (\u0648\u0642\u062f \u0623\u0633\u0644\u0645 \u0628\u0639\u062f \u0630\u0644\u0643 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647)\u060c \u0641\u0642\u0627\u0644: \u0648\u0647\u0630\u0627 \u0627\u0644\u0645\u062b\u0646\u0649 \u0634\u064a\u062e\u0646\u0627 \u0648\u0635\u0627\u062d\u0628 \u062d\u0631\u0628\u0646\u0627\u060c \u0641\u0642\u0627\u0644 \u0627\u0644\u0645\u062b\u0646\u0649: \u0642\u062f \u0633\u0645\u0639\u062a \u0645\u0642\u0627\u0644\u062a\u0643 \u064a\u0627 \u0623\u062e\u0627 \u0642\u0631\u064a\u0634\u060c \u0648\u0627\u0644\u062c\u0648\u0627\u0628 \u0641\u064a\u0647 \u062c\u0648\u0627\u0628 \u0647\u0627\u0646\u0626 \u0628\u0646 \u0642\u0628\u064a\u0635\u0629 \u0641\u064a \u062a\u0631\u0643\u0646\u0627 \u062f\u064a\u0646\u0646\u0627 \u0648\u0645\u062a\u0627\u0628\u0639\u062a\u0646\u0627 \u062f\u064a\u0646\u0643\u060c \u0648\u0625\u0646\u0627 \u0625\u0646\u0645\u0627 \u0646\u0632\u0644\u0646\u0627 \u0628\u064a\u0646 \u0635\u064e\u0631\u064e\u064a\u064e\u064a\u0646 \u0623\u062d\u062f\u0647\u0645\u0627 \u0627\u0644\u064a\u0645\u0627\u0645\u0629 \u0648\u0627\u0644\u0622\u062e\u0631 \u0627\u0644\u0633\u064e\u0651\u0645\u0627\u0645\u0629\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \u0645\u0627 \u0647\u0630\u0627\u0646 \u0627\u0644\u0635\u0631\u064a\u0627\u0646\u061f \u0642\u0627\u0644: \u0623\u0646\u0647\u0627\u0631 \u0643\u0633\u0631\u0649 \u0648\u0645\u064a\u0627\u0647 \u0627\u0644\u0639\u0631\u0628\u060c \u0641\u0623\u0645\u0627 \u0645\u0627 \u0643\u0627\u0646 \u0645\u0646 \u0623\u0646\u0647\u0627\u0631 \u0643\u0633\u0631\u0649 \u0641\u0630\u0646\u0628 \u0635\u0627\u062d\u0628\u0647 \u063a\u064a\u0631 \u0645\u063a\u0641\u0648\u0631 \u0648\u0639\u0630\u0631\u0647 \u063a\u064a\u0631 \u0645\u0642\u0628\u0648\u0644\u060c \u0648\u0625\u0646\u0627 \u0625\u0646\u0645\u0627 \u0646\u0632\u0644\u0646\u0627 \u0639\u0644\u0649 \u0639\u0647\u062f \u0623\u062e\u0630\u0647 \u0639\u0644\u064a\u0646\u0627 \u0643\u0633\u0631\u0649 \u0623\u0644\u0627 \u0646\u064f\u062d\u062f\u0650\u062b \u062d\u062f\u062b\u064b\u0627 \u0648\u0644\u0627 \u0646\u0623\u0648\u064a \u0645\u064f\u062d\u062f\u0650\u062b\u064b\u0627\u060c \u0648\u0625\u0646\u064a \u0623\u0631\u0649 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0627\u0644\u0630\u064a \u062a\u062f\u0639\u0648\u0646\u0627 \u0625\u0644\u064a\u0647 \u064a\u0627 \u0623\u062e\u0627 \u0642\u0631\u064a\u0634 \u0645\u0645\u0627 \u062a\u0643\u0631\u0647 \u0627\u0644\u0645\u0644\u0648\u0643\u060c \u0641\u0625\u0646 \u0623\u062d\u0628\u0628\u062a \u0623\u0646 \u0646\u0623\u0648\u064a\u0643 \u0648\u0646\u0646\u0635\u0631\u0643 \u0645\u0645\u0627 \u064a\u0644\u064a \u0645\u064a\u0627\u0647 \u0627\u0644\u0639\u0631\u0628 \u0641\u0639\u0644\u0646\u0627\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \u0645\u0627 \u0623\u0633\u0623\u062a\u0645 \u0641\u064a \u0627\u0644\u0631\u062f \u0625\u0630 \u0623\u0641\u0635\u062d\u062a\u0645 \u0628\u0627\u0644\u0635\u062f\u0642\u060c \u0648\u0625\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0644\u0646 \u064a\u0646\u0635\u0631\u0647 \u0625\u0644\u0627 \u0645\u0646 \u062d\u0627\u0637\u0647 \u0645\u0646 \u062c\u0645\u064a\u0639 \u062c\u0648\u0627\u0646\u0628\u0647\u060c \u0623\u0631\u0623\u064a\u062a\u0645 \u0625\u0646 \u0644\u0645 \u062a\u064e\u0644\u0628\u062b\u0648\u0627 \u0625\u0644\u0627 \u0642\u0644\u064a\u0644\u0627\u064b \u062d\u062a\u0649 \u064a\u064f\u0648\u0631\u062b\u0643\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0623\u0631\u0636\u0647\u0645 \u0648\u062f\u064a\u0627\u0631\u0647\u0645 \u0648\u064a\u064f\u0641\u0631\u0634\u0643\u0645 \u0646\u0633\u0627\u0621\u0647\u0645\u060c \u0623\u062a\u064f\u0633\u0628\u0650\u0651\u062d\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u062a\u064f\u0642\u062f\u0650\u0651\u0633\u0648\u0646\u0647\u061f \u0641\u0642\u0627\u0644 \u0627\u0644\u0646\u0639\u0645\u0627\u0646 \u0628\u0646 \u0634\u0631\u064a\u0643: \u0627\u0644\u0644\u0647\u0645 \u0641\u0644\u0643 \u0630\u0627\u0643.","\u0627\u0644\u0645\u0639\u0627\u0646\u064a: [ \u0635\u064e\u0631\u064e\u064a\u064e\u064a\u0646: \u0645\u062b\u0646\u0649 \u0635\u064e\u0631\u0649\u060c \u0623\u064a \u062d\u062f\u064e\u0651\u064a\u0646 \u0623\u0648 \u0637\u0631\u0641\u064a\u0646 \u062d\u0627\u062c\u0632\u064a\u0646 | \u0627\u0644\u064a\u0645\u0627\u0645\u0629: \u0645\u0646\u0637\u0642\u0629 \u0645\u0639\u0631\u0648\u0641\u0629 \u0641\u064a \u0646\u062c\u062f | \u0627\u0644\u0633\u064e\u0651\u0645\u0627\u0645\u0629: \u0645\u0648\u0636\u0639 \u0623\u0648 \u062d\u062f\u0651 \u064a\u0642\u0627\u0628\u0644 \u0627\u0644\u064a\u0645\u0627\u0645\u0629 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0633\u064a\u0627\u0642 | \u0645\u064f\u062d\u062f\u0650\u062b\u064b\u0627: \u0645\u0646 \u064a\u064f\u062d\u062f\u0650\u062b \u0623\u0645\u0631\u064b\u0627 \u062c\u062f\u064a\u062f\u064b\u0627 \u0645\u062e\u0627\u0644\u0641\u064b\u0627 \u0644\u0645\u0627 \u062a\u0639\u0627\u0647\u062f\u0648\u0627 \u0639\u0644\u064a\u0647 ]."],t.s)
B.a_s=new A.a("B1_C26_T4","\u0627\u0644\u0645\u0641\u0627\u0648\u0636\u0627\u062a \u0645\u0639 \u0628\u0646\u064a \u0634\u064a\u0628\u0627\u0646",B.aSy)
B.aTW=s(["\u0643\u0627\u0646 \u0637\u0644\u0628\u064f \u0627\u0644\u0646\u0628\u064a \ufdfa \u0627\u0644\u0646\u0635\u0631\u0629\u064e \u0645\u0646 \u062e\u0627\u0631\u062c \u0645\u0643\u0629 \u064a\u0646\u0634\u0637 \u0628\u0634\u0643\u0644 \u0645\u0644\u062d\u0648\u0638 \u0628\u0639\u062f \u0623\u0646 \u0627\u0634\u062a\u062f\u064e\u0651 \u0627\u0644\u0623\u0630\u0649 \u0639\u0644\u064a\u0647\u060c \u0639\u0642\u0628 \u0648\u0641\u0627\u0629 \u0639\u0645\u0647 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u064a\u064e\u062d\u0645\u064a\u0647 \u0645\u0646 \u0642\u0631\u064a\u0634\u060c \u0648\u0630\u0644\u0643 \u0644\u0623\u0646 \u0645\u0646 \u064a\u062d\u0645\u0644 \u0627\u0644\u062f\u0639\u0648\u0629 \u0644\u0646 \u064a\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u062a\u062d\u0631\u0643 \u0627\u0644\u0641\u0639\u0651\u0627\u0644 \u0648\u062d\u064e\u0645\u0644 \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u062a\u0648\u0641\u064a\u0631\u064e \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0644\u0647\u0627 \u0641\u064a \u062c\u0648\u064d\u0651 \u0645\u0646 \u0627\u0644\u0639\u0646\u0641 \u0648\u0627\u0644\u0636\u0639\u0641 \u0648\u0627\u0644\u0625\u0631\u0647\u0627\u0628\u060c \u0648\u0643\u0627\u0646 \u0639\u064e\u0631\u0636\u064f\u0647 \ufdfa \u0646\u0641\u0633\u064e\u0647 \u0639\u0644\u0649 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0625\u0646\u0645\u0627 \u0647\u0648 \u0628\u0623\u0645\u0631 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644\u060c \u0644\u0627 \u0645\u062c\u0631\u062f \u0627\u062c\u062a\u0647\u0627\u062f \u0645\u0646\u0647 \u0627\u0642\u062a\u0636\u062a\u0647 \u0638\u0631\u0648\u0641 \u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0648\u0643\u0627\u0646 \ufdfa \u064a\u064e\u062d\u0635\u064f\u0631 \u0637\u0644\u0628\u064e \u0627\u0644\u0646\u0635\u0631\u0629 \u0628\u0632\u0639\u0645\u0627\u0621 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0648\u0630\u0648\u064a \u0627\u0644\u0634\u0631\u0641 \u0648\u0627\u0644\u0645\u0643\u0627\u0646\u0629 \u0645\u0645\u0646 \u0644\u0647\u0645 \u0623\u062a\u0628\u0627\u0639 \u064a\u0633\u0645\u0639\u0648\u0646 \u0644\u0647\u0645 \u0648\u064a\u0637\u064a\u0639\u0648\u0646\u060c \u0644\u0623\u0646 \u0647\u0624\u0644\u0627\u0621 \u0647\u0645 \u0627\u0644\u0642\u0627\u062f\u0631\u0648\u0646 \u0639\u0644\u0649 \u062a\u0648\u0641\u064a\u0631 \u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0644\u0644\u062f\u0639\u0648\u0629 \u0648\u0635\u0627\u062d\u0628\u0647\u0627.","\u0648\u0642\u062f \u0631\u0641\u0636 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0623\u0646 \u064a\u064f\u0639\u0637\u064a\u064e \u0627\u0644\u0642\u0648\u0649 \u0627\u0644\u0645\u0633\u062a\u0639\u062f\u0629 \u0644\u062a\u0642\u062f\u064a\u0645 \u0646\u0635\u0631\u062a\u0647\u0627 \u0623\u064a\u064e\u0651 \u0636\u0645\u0627\u0646\u0627\u062a \u0628\u0623\u0646 \u064a\u0643\u0648\u0646 \u0644\u0623\u0634\u062e\u0627\u0635\u0647\u0645 \u0634\u064a\u0621 \u0645\u0646 \u0627\u0644\u062d\u0643\u0645 \u0648\u0627\u0644\u0633\u0644\u0637\u0627\u0646 \u062b\u0645\u0646\u0627\u064b \u0639\u0644\u0649 \u0645\u0627 \u064a\u0642\u062f\u0645\u0648\u0646\u060c \u0648\u0630\u0644\u0643 \u0644\u0623\u0646 \u0627\u0644\u062f\u0639\u0648\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a\u0629 \u0625\u0646\u0645\u0627 \u0647\u064a \u062f\u0639\u0648\u0629 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0641\u0627\u0644\u0634\u0631\u0637 \u0627\u0644\u0623\u0633\u0627\u0633\u064a \u0641\u064a\u0645\u0646 \u064a\u0624\u0645\u0646 \u0628\u0647\u0627 \u0648\u064a\u0633\u062a\u0639\u062f \u0644\u0646\u0635\u0631\u062a\u0647\u0627 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0625\u062e\u0644\u0627\u0635\u064f \u0644\u0644\u0647 \u0648\u0646\u0634\u062f\u0627\u0646\u064f \u0631\u0636\u0627\u0647 \u0647\u0645\u0627 \u0627\u0644\u063a\u0627\u064a\u0629 \u0627\u0644\u062a\u064a \u064a\u0633\u0639\u0649 \u0625\u0644\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0646\u0635\u0631\u0629 \u0648\u0627\u0644\u062a\u0636\u062d\u064a\u0629\u060c \u0644\u0627 \u0637\u0645\u0639\u0627\u064b \u0641\u064a \u0646\u0641\u0648\u0630 \u0648\u0644\u0627 \u0631\u063a\u0628\u0629\u064b \u0641\u064a \u0633\u0644\u0637\u0627\u0646\u060c \u0625\u0630 \u0627\u0644\u063a\u0627\u064a\u0629\u064f \u0627\u0644\u062a\u064a \u064a\u0636\u0639\u0647\u0627 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0644\u0644\u0634\u064a\u0621 \u0647\u064a \u0627\u0644\u062a\u064a \u062a\u064f\u0643\u064a\u0650\u0651\u0641 \u0646\u0634\u0627\u0637\u064e\u0647 \u0641\u064a \u0627\u0644\u0633\u0639\u064a \u0625\u0644\u064a\u0647.","\u0641\u0644\u0627 \u0628\u062f \u0625\u0630\u0646 \u0645\u0646 \u0623\u0646 \u062a\u062a\u062c\u0631\u062f \u0627\u0644\u063a\u0627\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u0645\u0646 \u0648\u0631\u0627\u0621 \u0646\u0635\u0631\u0629 \u0627\u0644\u062f\u0639\u0648\u0629 \u0639\u0646 \u0623\u064a \u0645\u0635\u0644\u062d\u0629 \u0645\u0627\u062f\u064a\u0629\u060c \u0636\u0645\u0627\u0646\u0627\u064b \u0644\u062f\u0648\u0627\u0645 \u0627\u0644\u062a\u0623\u064a\u064a\u062f \u0644\u0647\u0627\u060c \u0648\u0635\u0648\u0646\u0627\u064b \u0644\u0647\u0627 \u0645\u0646 \u0627\u0644\u0627\u0646\u062d\u0631\u0627\u0641\u060c \u0648\u0636\u0645\u0627\u0646\u0627\u064b \u0644\u0623\u0642\u0635\u0649 \u0645\u0627 \u064a\u0645\u0643\u0646 \u0645\u0646 \u0628\u0630\u0644 \u0627\u0644\u062f\u0639\u0645 \u0648\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062a\u0636\u062d\u064a\u0627\u062a \u0641\u064a \u0633\u0628\u064a\u0644\u0647\u0627\u060c \u0641\u064a\u062c\u0628 \u0639\u0644\u0649 \u0643\u0644 \u0645\u0646 \u064a\u0631\u064a\u062f \u0623\u0646 \u064a\u0644\u062a\u0632\u0645 \u0628\u0627\u0644\u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u062a\u064a \u062a\u062f\u0639\u0648 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0623\u0644\u0627 \u064a\u0634\u062a\u0631\u0637 \u0639\u0644\u064a\u0647\u0627 \u0645\u0646\u0635\u0628\u0627\u064b \u0623\u0648 \u0639\u064e\u0631\u0636\u0627\u064b \u0645\u0646 \u0623\u0639\u0631\u0627\u0636 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0644\u0623\u0646 \u0647\u0630\u0647 \u0627\u0644\u062f\u0639\u0648\u0629 \u0644\u0644\u0647 \u0648\u0627\u0644\u0623\u0645\u0631 \u0644\u0644\u0647 \u064a\u0636\u0639\u0647 \u062d\u064a\u062b \u064a\u0634\u0627\u0621\u060c \u0648\u0627\u0644\u062f\u0627\u062e\u0644 \u0641\u064a\u0647\u0627 \u0625\u0646\u0645\u0627 \u064a\u0631\u064a\u062f \u0627\u0628\u062a\u062f\u0627\u0621 \u0648\u062c\u0647\u064e \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0639\u0645\u0644\u064e \u0644\u0631\u0641\u0639 \u0631\u0627\u064a\u062a\u0647\u060c \u0623\u0645\u0627 \u0625\u0646 \u0643\u0627\u0646 \u0627\u0644\u0645\u0646\u0635\u0628 \u0647\u0648 \u0634\u0627\u063a\u0644\u0647 \u0641\u062a\u0644\u0643 \u0639\u0644\u0627\u0645\u0629 \u062e\u0637\u064a\u0631\u0629 \u062a\u064f\u0646\u0628\u0626 \u0639\u0646 \u062f\u064e\u062e\u064e\u0646 \u0641\u064a \u0646\u064a\u0629 \u0635\u0627\u062d\u0628\u0647\u060c \u0648\u0644\u0647\u0630\u0627 \u0642\u0627\u0644 \u064a\u062d\u064a\u0649 \u0628\u0646 \u0645\u0639\u0627\u0630 \u0627\u0644\u0631\u0627\u0632\u064a: \u0644\u0627 \u064a\u064f\u0641\u0644\u062d \u0645\u0646 \u0634\u0645\u0645\u062a \u0645\u0646\u0647 \u0631\u0627\u0626\u062d\u0629 \u0627\u0644\u0631\u064a\u0627\u0633\u0629.","\u0648\u0645\u0646 \u0635\u0641\u0629 \u0627\u0644\u0646\u0635\u0631\u0629 \u0627\u0644\u062a\u064a \u0643\u0627\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u0637\u0644\u0628\u0647\u0627 \u0644\u062f\u0639\u0648\u062a\u0647 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0623\u0647\u0644 \u0627\u0644\u0646\u0635\u0631\u0629 \u063a\u064a\u0631 \u0645\u0631\u062a\u0628\u0637\u064a\u0646 \u0628\u0645\u0639\u0627\u0647\u062f\u0627\u062a \u062f\u0648\u0644\u064a\u0629 \u062a\u062a\u0646\u0627\u0642\u0636 \u0645\u0639 \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0646 \u0627\u0644\u062a\u062d\u0631\u0631 \u0645\u0646\u0647\u0627\u060c \u0644\u0623\u0646 \u0627\u062d\u062a\u0636\u0627\u0646\u0647\u0645 \u0644\u0647\u0627 \u0648\u0627\u0644\u062d\u0627\u0644\u0629\u064f \u0647\u0630\u0647 \u064a\u064f\u0639\u0631\u0650\u0651\u0636\u0647\u0627 \u0644\u062e\u0637\u0631 \u0627\u0644\u0642\u0636\u0627\u0621 \u0639\u0644\u064a\u0647\u0627 \u0645\u0646 \u0642\u0650\u0628\u064e\u0644 \u0627\u0644\u062f\u0648\u0644 \u0627\u0644\u062a\u064a \u062a\u062c\u062f \u0641\u064a \u0627\u0644\u062f\u0639\u0648\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a\u0629 \u062e\u0637\u0631\u0627\u064b \u0639\u0644\u064a\u0647\u0627 \u0648\u062a\u0647\u062f\u064a\u062f\u0627\u064b \u0644\u0645\u0635\u0627\u0644\u062d\u0647\u0627\u060c \u0648\u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0645\u0634\u0631\u0648\u0637\u0629 \u0623\u0648 \u0627\u0644\u062c\u0632\u0626\u064a\u0629 \u0644\u0627 \u062a\u062d\u0642\u0642 \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u0645\u0642\u0635\u0648\u062f\u060c \u0641\u0644\u0646 \u064a\u064e\u062e\u0648\u0636 \u0628\u0646\u0648 \u0634\u064a\u0628\u0627\u0646 \u062d\u0631\u0628\u0627\u064b \u0636\u062f \u0643\u0633\u0631\u0649 \u0644\u0648 \u0623\u0631\u0627\u062f \u0627\u0644\u0642\u0628\u0636\u064e \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u062a\u0633\u0644\u064a\u0645\u0647\u060c \u0648\u0644\u0646 \u064a\u062e\u0648\u0636\u0648\u0647\u0627 \u0644\u0648 \u0623\u0631\u0627\u062f \u0645\u0647\u0627\u062c\u0645\u062a\u064e\u0647 \ufdfa \u0648\u0623\u062a\u0628\u0627\u0639\u0647\u060c \u0648\u0628\u0630\u0644\u0643 \u0641\u0634\u0644\u062a \u0627\u0644\u0645\u0628\u0627\u062d\u062b\u0627\u062a.","\u0648\u062d\u064a\u0646 \u0639\u0631\u0636 \u0627\u0644\u0645\u062b\u0646\u0649 \u0628\u0646 \u062d\u0627\u0631\u062b\u0629 \u0639\u0644\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u062d\u0645\u0627\u064a\u062a\u064e\u0647 \u0639\u0644\u0649 \u0645\u064a\u0627\u0647 \u0627\u0644\u0639\u0631\u0628 \u062f\u0648\u0646 \u0645\u064a\u0627\u0647 \u0627\u0644\u0641\u0631\u0633\u060c \u0643\u0627\u0646 \u0631\u062f\u0647 \ufdfa: \xab\u0625\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0644\u0646 \u064a\u0646\u0635\u0631\u0647 \u0625\u0644\u0627 \u0645\u0646 \u062d\u0627\u0637\u0647 \u0645\u0646 \u062c\u0645\u064a\u0639 \u062c\u0648\u0627\u0646\u0628\u0647\xbb\u060c \u0648\u0645\u0646 \u064a\u064e\u0633\u0628\u064f\u0631 \u0623\u063a\u0648\u0627\u0631 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0628\u0639\u064a\u062f\u0629 \u064a\u064e\u0631\u064e \u0628\u064f\u0639\u062f\u064e \u0627\u0644\u0646\u0638\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a \u0627\u0644\u0646\u0628\u0648\u064a \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u064f\u0633\u0627\u0645\u0649.","\u0648\u0643\u0627\u0646 \u0645\u0648\u0642\u0641 \u0628\u0646\u064a \u0634\u064a\u0628\u0627\u0646 \u064a\u062a\u0633\u0645 \u0628\u0627\u0644\u0625\u0631\u064a\u062d\u064a\u0629 \u0648\u0627\u0644\u062e\u064f\u0644\u064f\u0642 \u0648\u0627\u0644\u0631\u062c\u0648\u0644\u0629\u060c \u0648\u064a\u0646\u0645\u0651 \u0639\u0646 \u062a\u0639\u0638\u064a\u0645 \u0647\u0630\u0627 \u0627\u0644\u0646\u0628\u064a \u0648\u0648\u0636\u0648\u062d \u0641\u064a \u0627\u0644\u0639\u0631\u0636 \u0648\u062a\u062d\u062f\u064a\u062f \u0644\u0645\u062f\u0649 \u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u062a\u064a \u064a\u0645\u0644\u0643\u0648\u0646\u0647\u0627\u060c \u0648\u0642\u062f \u0628\u064a\u0651\u0646\u0648\u0627 \u0623\u0646 \u0623\u0645\u0631 \u0627\u0644\u062f\u0639\u0648\u0629 \u0645\u0645\u0627 \u062a\u0643\u0631\u0647\u0647 \u0627\u0644\u0645\u0644\u0648\u0643\u060c \u062b\u0645 \u0642\u062f\u064e\u0651\u0631 \u0627\u0644\u0644\u0647 \u0644\u0634\u064a\u0628\u0627\u0646 \u0628\u0639\u062f \u0639\u0634\u0631 \u0633\u0646\u064a\u0646 \u0623\u0648 \u064a\u0632\u064a\u062f \u0623\u0646 \u062a\u062d\u0645\u0644 \u0647\u064a \u0627\u0628\u062a\u062f\u0627\u0621\u064b \u0639\u0628\u0621\u064e \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0644\u0648\u0643 \u0628\u0639\u062f \u0623\u0646 \u0623\u0634\u0631\u0642 \u0642\u0644\u0628\u064f\u0647\u0627 \u0628\u0646\u0648\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0643\u0627\u0646 \u0627\u0644\u0645\u062b\u0646\u0649 \u0628\u0646 \u062d\u0627\u0631\u062b\u0629 \u0627\u0644\u0634\u064a\u0628\u0627\u0646\u064a \u0635\u0627\u062d\u0628\u064e \u062d\u0631\u0628\u0647\u0645 \u0648\u0628\u0637\u0644\u064e\u0647\u0645 \u0627\u0644\u0645\u0650\u063a\u0648\u0627\u0631 \u0627\u0644\u0630\u064a \u0642\u0627\u062f \u0627\u0644\u0641\u062a\u0648\u062d \u0641\u064a \u0623\u0631\u0636 \u0627\u0644\u0639\u0631\u0627\u0642 \u0641\u064a \u062e\u0644\u0627\u0641\u0629 \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0641\u0643\u0627\u0646 \u0648\u0642\u0648\u0645\u0647 \u0645\u0646 \u0623\u062c\u0631\u0623 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0628\u0639\u062f \u0625\u0633\u0644\u0627\u0645\u0647\u0645 \u0639\u0644\u0649 \u0642\u062a\u0627\u0644 \u0627\u0644\u0641\u0631\u0633\u060c \u0628\u064a\u0646\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u0641\u064a \u062c\u0627\u0647\u0644\u064a\u062a\u0647\u0645 \u064a\u064e\u0631\u0647\u064e\u0628\u0648\u0646 \u0627\u0644\u0641\u0631\u0633 \u0648\u0644\u0627 \u064a\u064f\u0641\u0643\u0631\u0648\u0646 \u0641\u064a \u0642\u062a\u0627\u0644\u0647\u0645\u060c \u0628\u0644 \u0625\u0646\u0647\u0645 \u0631\u062f\u0648\u0627 \u062f\u0639\u0648\u0629 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0639\u062f \u0642\u0646\u0627\u0639\u062a\u0647\u0645 \u0628\u0647\u0627 \u0644\u0627\u062d\u062a\u0645\u0627\u0644 \u0623\u0646 \u062a\u064f\u0644\u062c\u0626\u0647\u0645 \u0625\u0644\u0649 \u0642\u062a\u0627\u0644 \u0627\u0644\u0641\u0631\u0633 \u0627\u0644\u0630\u064a \u0644\u0645 \u064a\u0643\u0648\u0646\u0648\u0627 \u064a\u064f\u0641\u0643\u0631\u0648\u0646 \u0641\u064a\u0647 \u0623\u0628\u062f\u0627\u064b\u060c \u0648\u0628\u0647\u0630\u0627 \u0646\u0639\u0644\u0645 \u0639\u0638\u0645\u0629 \u0647\u0630\u0627 \u0627\u0644\u062f\u064a\u0646 \u0627\u0644\u0630\u064a \u0631\u0641\u0639 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0641\u062c\u0639\u0644\u0647\u0645 \u0633\u0627\u062f\u0629 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0645\u0627 \u064a\u0646\u062a\u0638\u0631\u0648\u0646 \u0641\u064a \u0623\u062e\u0631\u0627\u0647\u0645 \u0645\u0646 \u0627\u0644\u0646\u0639\u064a\u0645 \u0627\u0644\u062f\u0627\u0626\u0645 \u0641\u064a \u062c\u0646\u0627\u062a \u0627\u0644\u0646\u0639\u064a\u0645."],t.s)
