B.aMC=s(["\u0643\u0627\u0646 \u0635\u0647\u064a\u0628 \u0628\u0646 \u0633\u0646\u0627\u0646 \u0627\u0644\u0646\u064e\u0651\u0645\u064e\u0631\u064a\u064f\u0651 \u0645\u0646 \u0627\u0644\u0646\u064e\u0651\u0645\u0650\u0631 \u0628\u0646 \u0642\u0627\u0633\u0637\u060c \u0623\u063a\u0627\u0631\u062a \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0631\u0648\u0645\u064f \u0641\u0633\u064f\u0628\u064a \u0635\u063a\u064a\u0631\u0627\u064b\u060c \u0648\u0646\u0634\u0623 \u0628\u064a\u0646 \u0623\u064a\u062f\u064a\u0647\u0645 \u0641\u0623\u062e\u0630 \u0644\u0633\u0627\u0646\u0647\u0645\u060c \u062b\u0645 \u062a\u0642\u0644\u064e\u0651\u0628 \u0641\u064a \u0627\u0644\u0631\u0642\u0650\u0651 \u062d\u062a\u0649 \u0627\u0628\u062a\u0627\u0639\u0647 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u062c\u062f\u0639\u0627\u0646 \u062b\u0645 \u0623\u0639\u062a\u0642\u0647\u060c \u0648\u062f\u062e\u0644 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064e \u0647\u0648 \u0648\u0639\u0645\u0627\u0631 \u0628\u0646 \u064a\u0627\u0633\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627 \u0641\u064a \u064a\u0648\u0645 \u0648\u0627\u062d\u062f.","\u0648\u0643\u0627\u0646\u062a \u0647\u062c\u0631\u0629 \u0635\u0647\u064a\u0628 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0645\u0634\u0647\u062f\u0627\u064b \u062a\u062a\u062c\u0644\u0649 \u0641\u064a\u0647 \u0631\u0648\u0639\u0629 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0639\u0638\u0645\u0629 \u0627\u0644\u062a\u062c\u0631\u062f \u0644\u0644\u0647\u060c \u0625\u0630 \u0636\u062d\u064e\u0651\u0649 \u0628\u0643\u0644 \u0645\u0627 \u064a\u0645\u0644\u0643 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0627\u0644\u0644\u062d\u0648\u0642 \u0628\u0643\u062a\u064a\u0628\u0629 \u0627\u0644\u062a\u0648\u062d\u064a\u062f\u060c \u0641\u0639\u0646 \u0623\u0628\u064a \u0639\u062b\u0645\u0627\u0646 \u0627\u0644\u0646\u0647\u062f\u064a \u0631\u062d\u0645\u0647 \u0627\u0644\u0644\u0647 \u0642\u0627\u0644: \u0628\u0644\u063a\u0646\u064a \u0623\u0646 \u0635\u0647\u064a\u0628\u0627\u064b \u062d\u064a\u0646 \u0623\u0631\u0627\u062f \u0627\u0644\u0647\u062c\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0642\u0627\u0644 \u0644\u0647 \u0623\u0647\u0644 \u0645\u0643\u0629: \u0623\u062a\u064a\u062a\u064e\u0646\u0627 \u0647\u0627\u0647\u0646\u0627 \u0635\u0639\u0644\u0648\u0643\u0627\u064b \u062d\u0642\u064a\u0631\u0627\u064b\u060c \u0641\u0643\u064e\u062b\u064f\u0631 \u0645\u0627\u0644\u064f\u0643 \u0639\u0646\u062f\u0646\u0627\u060c \u0648\u0628\u0644\u063a\u062a\u064e \u0645\u0627 \u0628\u0644\u063a\u062a\u064e\u060c \u062b\u0645 \u062a\u0646\u0637\u0644\u0642 \u0628\u0646\u0641\u0633\u0643 \u0648\u0645\u0627\u0644\u0643\u061f \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0643\u0648\u0646 \u0630\u0644\u0643\u060c \u0641\u0642\u0627\u0644: \u0623\u0631\u0623\u064a\u062a\u0645 \u0625\u0646 \u062a\u0631\u0643\u062a\u064f \u0645\u0627\u0644\u064a \u062a\u064f\u062e\u0644\u064f\u0651\u0648\u0646 \u0633\u0628\u064a\u0644\u064a\u061f \u0642\u0627\u0644\u0648\u0627: \u0646\u0639\u0645\u060c \u0641\u062c\u0639\u0644 \u0644\u0647\u0645 \u0645\u0627\u0644\u0647 \u0623\u062c\u0645\u0639\u060c \u0641\u0628\u0644\u063a \u0630\u0644\u0643 \u0627\u0644\u0646\u0628\u064a\u064e\u0651 \ufdfa \u0641\u0642\u0627\u0644: \xab\u0631\u0628\u062d \u0635\u0647\u064a\u0628\u064c\u060c \u0631\u0628\u062d \u0635\u0647\u064a\u0628\u064c\xbb.","\u0648\u0639\u0646 \u0639\u0643\u0631\u0645\u0629 \u0631\u062d\u0645\u0647 \u0627\u0644\u0644\u0647 \u0642\u0627\u0644: \u0644\u0645\u0627 \u062e\u0631\u062c \u0635\u0647\u064a\u0628 \u0645\u0647\u0627\u062c\u0631\u0627\u064b \u062a\u0628\u0639\u0647 \u0623\u0647\u0644 \u0645\u0643\u0629\u060c \u0641\u0646\u062b\u064e\u0644 \u0643\u0646\u0627\u0646\u062a\u064e\u0647\u060c \u0641\u0623\u062e\u0631\u062c \u0645\u0646\u0647\u0627 \u0623\u0631\u0628\u0639\u064a\u0646 \u0633\u0647\u0645\u0627\u064b\u060c \u0648\u0642\u0627\u0644: \u0644\u0627 \u062a\u0635\u0644\u0648\u0646 \u0625\u0644\u064a\u064e\u0651 \u062d\u062a\u0649 \u0623\u0636\u0639 \u0641\u064a \u0643\u0644 \u0631\u062c\u0644 \u0645\u0646\u0643\u0645 \u0633\u0647\u0645\u0627\u064b\u060c \u062b\u0645 \u0623\u0635\u064a\u0631 \u0628\u0639\u062f \u0625\u0644\u0649 \u0627\u0644\u0633\u064a\u0641 \u0641\u062a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646\u064a \u0631\u062c\u0644\u060c \u0648\u0642\u062f \u062e\u0644\u064e\u0651\u0641\u062a\u064f \u0628\u0645\u0643\u0629 \u0641\u064a\u0646\u062a\u064a\u0646 \u0641\u0647\u0645\u0627 \u0644\u0643\u0645\u060c \u0648\u0642\u0627\u0644 \u0639\u0643\u0631\u0645\u0629: \u0648\u0646\u0632\u0644\u062a \u0639\u0644\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa: \ufd3f\u0648\u064e\u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0645\u064e\u0646 \u064a\u064e\u0634\u0631\u0650\u064a \u0646\u064e\u0641\u0633\u064e\u0647\u064f \u0627\u0628\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u0645\u064e\u0631\u0636\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0621\u064f\u0648\u0641\u064c \u0628\u0650\u0627\u0644\u0639\u0650\u0628\u064e\u0627\u062f\u0650\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0628\u0642\u0631\u0629\u060c \u0641\u0644\u0645\u0627 \u0631\u0622\u0647 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0642\u0627\u0644: \xab\u0623\u0628\u0627 \u064a\u062d\u064a\u0649\u060c \u0631\u0628\u062d \u0627\u0644\u0628\u064a\u0639\xbb\u060c \u0648\u062a\u0644\u0627 \u0639\u0644\u064a\u0647 \u0627\u0644\u0622\u064a\u0629.","\u0644\u0643\u0623\u0646 \u0635\u0647\u064a\u0628\u0627\u064b \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u064a\u064f\u0642\u062f\u0650\u0651\u0645 \u0627\u0644\u062f\u0644\u064a\u0644 \u0627\u0644\u0642\u0627\u0637\u0639 \u0639\u0644\u0649 \u0641\u0633\u0627\u062f \u0639\u0642\u0644 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u0627\u062f\u064a\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0632\u0646\u0648\u0646 \u062d\u0631\u0643\u0627\u062a \u0627\u0644\u062a\u0627\u0631\u064a\u062e \u0648\u0623\u062d\u062f\u0627\u062b\u0647 \u0628\u0645\u064a\u0632\u0627\u0646 \u0627\u0644\u0645\u0627\u062f\u0629 \u0648\u062d\u062f\u0647\u0627\u060c \u0641\u0623\u064a\u0646 \u0627\u0644\u0645\u0627\u062f\u0629 \u0627\u0644\u062a\u064a \u0633\u064a\u0643\u0633\u0628\u0647\u0627 \u0641\u064a \u0647\u062c\u0631\u062a\u0647 \u0648\u0627\u0644\u062a\u064a \u0636\u062d\u064e\u0651\u0649 \u0645\u0646 \u0623\u062c\u0644\u0647\u0627 \u0628\u0643\u0644 \u0645\u0627 \u064a\u0645\u0644\u0643\u061f \u0623\u0643\u0627\u0646 \u064a\u0646\u062a\u0638\u0631 \u0623\u0646 \u064a\u064f\u0639\u0637\u064a\u0647 \u0645\u062d\u0645\u062f\u064c \ufdfa \u0645\u0646\u0635\u0628\u0627\u064b \u064a\u064f\u0639\u0648\u0650\u0651\u0636\u0647 \u0639\u0645\u0627 \u0641\u0642\u062f\u061f \u0623\u0645 \u0643\u0627\u0646 \u064a\u064f\u0645\u0646\u0650\u0651\u064a\u0647 \u0628\u0627\u0644\u0639\u064a\u0634 \u0627\u0644\u0641\u0627\u062e\u0631 \u0641\u064a \u062c\u0648\u0627\u0631 \u0623\u0647\u0644 \u064a\u062b\u0631\u0628\u061f \u0645\u0627 \u0641\u0639\u0644 \u0635\u0647\u064a\u0628\u064c \u0630\u0644\u0643\u060c \u0648\u0645\u0627 \u0627\u0646\u062d\u0627\u0632 \u0625\u0644\u0649 \u0627\u0644\u0641\u0626\u0629 \u0627\u0644\u0645\u0624\u0645\u0646\u0629 \u0625\u0644\u0627 \u0627\u0628\u062a\u063a\u0627\u0621\u064e \u0645\u0631\u0636\u0627\u0629 \u0627\u0644\u0644\u0647\u060c \u0628\u0627\u0644\u063a\u0627\u064b \u0645\u0627 \u0628\u0644\u063a \u0627\u0644\u062b\u0645\u0646\u060c \u0644\u064a\u0636\u0631\u0628 \u0644\u0634\u0628\u0627\u0628 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0645\u062b\u0644\u0627\u064b \u0641\u064a \u0627\u0644\u062a\u0636\u062d\u064a\u0629 \u0639\u0632\u064a\u0632\u0629 \u0627\u0644\u0645\u0646\u0627\u0644\u060c \u0639\u0633\u0627\u0647\u0645 \u064a\u0633\u064a\u0631\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u062f\u0631\u0628 \u0648\u064a\u0642\u062a\u0641\u0648\u0646 \u0627\u0644\u0623\u062b\u0631.","\u0648\u0645\u0627 \u0643\u0627\u0646\u062a \u0647\u0630\u0647 \u0627\u0644\u0645\u0648\u0627\u0642\u0641 \u0627\u0644\u0631\u0627\u0626\u0639\u0629 \u0643\u0644\u064e\u0651 \u0645\u0634\u0627\u0647\u062f \u0627\u0644\u0639\u0638\u0645\u0629 \u0641\u064a \u0627\u0644\u0647\u062c\u0631\u0629 \u0627\u0644\u0645\u0628\u0627\u0631\u0643\u0629\u060c \u0628\u0644 \u0627\u0645\u062a\u0644\u0623 \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u062b \u0627\u0644\u0639\u0638\u064a\u0645 \u0628\u0643\u062b\u064a\u0631 \u0645\u0646 \u0635\u0648\u0631 \u0627\u0644\u062a\u062c\u0631\u062f \u0648\u0627\u0644\u062a\u0636\u062d\u064a\u0629\u060c \u0627\u0644\u062a\u064a \u062a\u0639\u0637\u064a \u0627\u0644\u0623\u0645\u0629 \u062f\u0631\u0648\u0633\u0627\u064b \u0628\u0644\u064a\u063a\u0629 \u0641\u064a \u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u062c\u062f \u0648\u062a\u062d\u0635\u064a\u0644 \u0627\u0644\u0639\u0632\u0629."],t.s)
