B.aM1=s(["\u062b\u0645\u0651\u0629\u064e \u0645\u064a\u0632\u0627\u0646\u064c \u062f\u0642\u064a\u0642\u064c \u064a\u064e\u0636\u0628\u0650\u0637 \u0639\u064e\u0644\u0627\u0642\u0629\u064e \u0627\u0644\u062f\u0627\u0639\u064a\u0629 \u0628\u0650\u0645\u064e\u0646 \u064a\u062a\u0639\u0627\u0645\u064e\u0644\u064f \u0645\u0639\u0647\u060c \u0641\u0644\u0627 \u0645\u0650\u0646\u064e\u0651\u0629\u064e \u062a\u064f\u062e\u0627\u0644\u0650\u0637 \u0627\u0644\u062f\u0639\u0648\u0629\u064e \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u063a\u064e\u0631\u064e\u0636\u064e \u064a\u064f\u0633\u0627\u0648\u0650\u0645 \u0639\u0644\u0649 \u0645\u0627 \u064a\u064f\u0642\u0627\u0644\u060c \u0648\u062a\u0628\u0642\u0649 \u0623\u0645\u0648\u0627\u0644\u064f \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u062d\u0627\u062c\u0627\u062a\u064f\u0647\u0627 \u0645\u064f\u0633\u062a\u0642\u0650\u0644\u064e\u0651\u0629\u064b \u0639\u0646 \u062d\u0627\u062c\u0629\u0650 \u0627\u0644\u062f\u0627\u0639\u064a\u0629 \u0627\u0644\u0634\u062e\u0635\u064a\u0629\u060c \u0648\u0625\u0646 \u0643\u0627\u0646 \u0645\u0627 \u064a\u064e\u0645\u0644\u0650\u0643\u0647 \u0627\u0644\u062f\u0627\u0639\u064a\u0629\u064f \u0634\u062e\u0635\u064a\u064b\u0651\u0627 \u0633\u064a\u064f\u0633\u0647\u0650\u0645\u064f \u0641\u064a \u062e\u062f\u0645\u0629 \u0627\u0644\u062f\u0639\u0648\u0629 \u0646\u0641\u0633\u0647\u0627\u060c \u0648\u0644\u0647\u0630\u0627 \u0644\u0645 \u064a\u0642\u0628\u064e\u0644 \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0646 \u064a\u0631\u0643\u0628\u064e \u0627\u0644\u0631\u0627\u062d\u0644\u0629 \u062d\u062a\u0649 \u0623\u062e\u0630\u0647\u0627 \u0628\u062b\u0645\u0646\u0647\u0627 \u0645\u0646 \u0623\u0628\u064a \u0628\u0643\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0648\u0628\u064e\u0642\u0650\u064a\u064e \u0627\u0644\u062b\u0645\u0646\u064f \u062f\u064e\u064a\u0646\u064b\u0627 \u0628\u0630\u0645\u062a\u0647\u060c \u0648\u0647\u0646\u0627 \u062a\u062a\u062c\u0644\u064e\u0651\u0649 \u062d\u0643\u0645\u0629\u064f \u0645\u0627 \u0641\u0639\u0644\u0647 \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0647\u064a \u062d\u0643\u0645\u0629\u064c \u064a\u062c\u062f\u064f\u0631 \u0628\u0650\u062d\u064f\u0645\u0627\u0629\u0650 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u062d\u064f\u0631\u064e\u0651\u0627\u0633\u0650 \u0627\u0644\u0639\u0642\u064a\u062f\u0629 \u0623\u0646 \u064a\u064e\u0641\u0642\u064e\u0647\u0648\u0647\u0627\u060c \u0641\u0644\u064a\u0633 \u0647\u0630\u0627 \u0631\u0641\u0636\u064b\u0627 \u0644\u0644\u0647\u062f\u064a\u064e\u0651\u0629\u060c \u0648\u0644\u064a\u0633 \u062a\u064e\u0631\u064e\u0641\u064f\u0651\u0639\u064b\u0627 \u0639\u0646 \u0628\u0650\u0631\u0650\u0651 \u0627\u0644\u0635\u0627\u062d\u0628\u060c \u0628\u0644 \u0647\u0648 \u0635\u064a\u0627\u0646\u0629\u064c \u0644\u0644\u062f\u0639\u0648\u0629 \u0623\u0646 \u062a\u062e\u062a\u0644\u0650\u0637\u064e \u0628\u0623\u064a\u0650\u0651 \u0638\u0650\u0644\u064d\u0651 \u0645\u0646 \u0638\u0650\u0644\u0627\u0644 \u0627\u0644\u0645\u0650\u0646\u064e\u0651\u0629\u060c \u0623\u0648 \u0623\u064a\u0650\u0651 \u0634\u064f\u0628\u0647\u0629\u064d \u0645\u0646 \u0634\u064f\u0628\u064e\u0647 \u0627\u0644\u0645\u0635\u0644\u062d\u0629.","\u0641\u0627\u0644\u062f\u0627\u0639\u064a\u0629\u064f \u0627\u0644\u0630\u064a \u064a\u062a\u0639\u0644\u064e\u0651\u0642\u064f \u0642\u064e\u0644\u0628\u064f\u0647 \u0628\u0645\u0627 \u064a\u064f\u0631\u0636\u064a \u0623\u0635\u062d\u0627\u0628\u064e \u0627\u0644\u0641\u0636\u0644 \u0639\u064e\u0644\u064e\u064a\u0647\u0650\u061b \u064a\u0641\u0642\u0650\u062f\u064f \u0635\u0644\u0627\u0628\u0629\u064e \u0645\u0648\u0642\u0641\u0650\u0647 \u0648\u062d\u0631\u064a\u064e\u0651\u0629\u064e \u0642\u0648\u0644\u0650\u0647\u060c \u0648\u064a\u064f\u0635\u0628\u0650\u062d\u064f \u0645\u064e\u062f\u064a\u0646\u064b\u0627 \u0644\u0645\u0646 \u0623\u0639\u0637\u0627\u0647\u060c \u0641\u0643\u064a\u0641 \u062d\u064a\u0646\u064e\u0647\u0627 \u064a\u0635\u062f\u064e\u0639\u064f \u0628\u0627\u0644\u062d\u0642\u0650\u0651 \u0625\u0646 \u062c\u0627\u0621 \u0639\u0644\u0649 \u063a\u064a\u0631\u0650 \u0645\u0627 \u064a\u064f\u0631\u0636\u064a \u0645\u064e\u0646 \u0623\u064e\u0646\u0639\u064e\u0645\u064e \u0639\u0644\u064a\u0647\u061f! \u0648\u0645\u0627 \u062a\u0623\u062e\u0651\u0631 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0648\u0645\u0627 \u0623\u0635\u0627\u0628\u0647\u0645 \u0645\u0646 \u0627\u0644\u0647\u064e\u0648\u0627\u0646 \u0625\u0644\u0627 \u064a\u0648\u0645\u064e \u0623\u0635\u0628\u062d\u062a \u0648\u0633\u0627\u0626\u0644\u064f \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u0627\u0644\u0639\u0627\u0645\u0644\u0648\u0646 \u0628\u0647\u0627 \u062e\u0627\u0636\u0639\u064a\u0646 \u0644\u0650\u0644\u064f\u063a\u0629\u0650 \u0627\u0644\u0645\u0627\u062f\u0629 \u0648\u0627\u0644\u0645\u0635\u0644\u062d\u0629\u060c \u0648\u064a\u064e\u0646\u062a\u0638\u0631\u064f \u0627\u0644\u0648\u0627\u062d\u062f\u064f \u0645\u0646\u0647\u0645 \u0631\u0627\u062a\u0628\u064b\u0627 \u0623\u0648 \u0645\u0627\u0644\u064b\u0627\u060c \u0648\u062d\u064a\u0646\u064e\u0626\u0630\u064d \u062a\u062d\u0648\u0651\u0644 \u0627\u0644\u0639\u0645\u0644\u064f \u0625\u0644\u0649 \u0639\u0645\u0644\u064d \u0645\u0627\u062f\u064a \u0641\u064e\u0642\u064e\u062f\u064e \u062c\u0648\u0647\u0631\u064e\u0647 \u0648\u063a\u0627\u064a\u062a\u064e\u0647\u060c \u0648\u0623\u0635\u0628\u062d \u0627\u0644\u0623\u0626\u0645\u0629\u064f \u0623\u064f\u062c\u064e\u0631\u0627\u0621\u064e \u0644\u0627 \u062f\u064f\u0639\u0627\u0629. "],t.s)
