B.ayW=s(["\u0627\u0644\u0644\u0647\u064f \u0633\u0628\u064f\u062d\u0627\u0646\u064e\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0645\u062a\u0651\u064e\u0635\u0650\u0641\u064c \u0628\u0635\u0641\u0627\u062a\u0650 \u0627\u0644\u062c\u064e\u0644\u0627\u0644\u0650 \u0648\u0627\u0644\u0643\u064e\u0645\u0627\u0644\u0650\u060c \u0648\u0642\u062f \u062d\u062f\u0651\u064e \u062d\u062f\u0648\u062f\u064b\u0627 \u0648\u0634\u0631\u0627\u0626\u0650\u0639\u064e\u060c \u0648\u0623\u0645\u0631 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621\u064e \u0648\u0627\u0644\u0645\u0631\u0633\u0644\u064a\u0646 \u0628\u062a\u0628\u0644\u064a\u063a\u0650\u0647\u0627\u061b \u0641\u0623\u0642\u0627\u0645 \u0627\u0644\u062d\u064f\u062c\u0651\u064e\u0629\u064e \u0639\u0644\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u0623\u0639\u0644\u064e\u0645\u064e\u0647\u0645 \u0628\u0627\u0644\u062d\u064e\u0644\u0627\u0644\u0650 \u0648\u0627\u0644\u062d\u0631\u0627\u0645\u0650.","\u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b\u0650 \u064a\u064f\u062e\u0628\u0650\u0631\u064f \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u064f \ufdfa \u0623\u0646\u0651\u064e \u0627\u0644\u0644\u0647\u064e \u0633\u064f\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u064e\u0649 \u064a\u064e\u063a\u0627\u0631\u064f\u060c \u0648\u0623\u0646\u0651\u064e \u063a\u064e\u064a\u0631\u062a\u064e\u0647 \u0623\u0646 \u064a\u064e\u0623\u062a\u064a\u064e \u0627\u0644\u0645\u0624\u0645\u0646\u064f \u0645\u0627 \u062d\u0631\u0651\u064e\u0645\u064e \u0627\u0644\u0644\u0647\u064f\u060c \u0648\u0645\u0639\u0646\u0627\u0647: \u0623\u0646\u0651\u064e \u063a\u064e\u064a\u0631\u062a\u064e\u0647 \u062b\u0627\u0628\u062a\u0629\u064c \u0644\u0623\u062c\u0644\u0650 \u0623\u0644\u0651\u064e\u0627 \u064a\u064e\u0623\u062a\u064a\u064e \u0627\u0644\u0645\u0624\u0645\u0646\u064f \u0645\u064e\u062d\u0627\u0631\u0650\u0645\u064e\u0647\u060c \u0648\u062e\u064e\u0635\u0651\u064e \u0627\u0644\u0645\u0624\u0645\u0646\u064e \u062f\u064f\u0648\u0646\u064e \u063a\u064a\u0631\u0650\u0647\u061b \u0644\u0623\u0646\u0651\u064e \u0627\u0646\u062a\u0647\u0627\u0643\u064e \u0627\u0644\u0645\u062d\u0627\u0631\u0650\u0645\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0645\u0624\u0645\u0646\u0650 \u0623\u0639\u0638\u064e\u0645\u064f \u0645\u0650\u0646 \u0648\u064f\u0642\u0648\u0639\u0650\u0647 \u0645\u0650\u0646 \u063a\u064e\u064a\u0631\u0650\u0647.","\u0648\u063a\u064a\u0631\u0629\u064f \u0627\u0644\u0644\u0647\u0650 \u062a\u0639\u0627\u0644\u0649 \u0645\u0646 \u062c\u0650\u0646\u0633\u0650 \u0635\u0650\u0641\u0627\u062a\u0650\u0647 \u0627\u0644\u062a\u064a \u064a\u062e\u062a\u064e\u0635\u0651\u064f \u0628\u0647\u0627\u061b \u0641\u0647\u064a \u0644\u064a\u0633\u062a \u0645\u0645\u0627\u062b\u0650\u0644\u0629\u064b \u0644\u063a\u064e\u064a\u0631\u0629\u0650 \u0627\u0644\u0645\u062e\u0644\u0648\u0642\u0650\u060c \u0628\u0644 \u0647\u064a \u0635\u0641\u0629\u064c \u062a\u0644\u064a\u0642\u064f \u0628\u0639\u064e\u0638\u064e\u0645\u062a\u0650\u0647 \u062f\u0648\u0646\u064e \u062a\u0643\u064a\u064a\u0641\u064d \u0623\u0648 \u062a\u0634\u0628\u064a\u0647\u064d \u0623\u0648 \u062a\u0639\u0637\u064a\u0644\u064d.","\u0648\u0641\u064a \u0627\u0644\u062d\u064e\u062f\u064a\u062b\u0650: \u0625\u062b\u0628\u0627\u062a\u064f \u0635\u0650\u0641\u0629\u0650 \u0627\u0644\u063a\u064e\u064a\u0631\u0629\u0650 \u0644\u0644\u0647\u0650 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0641\u064a\u0647: \u0627\u0644\u062a\u062d\u0630\u064a\u0631\u064f \u0645\u0650\u0646 \u0627\u0642\u062a\u0631\u0627\u0641\u0650 \u0627\u0644\u0645\u062d\u064e\u0631\u0651\u064e\u0645\u0627\u062a\u0650."],t.s)
