B.avd=s(["\u0643\u0627\u0646 \u0627\u0628\u0646 \u0627\u0644\u062c\u0648\u0632\u064a \u064a\u062a\u0635\u062f\u0631 \u0627\u0644\u0648\u0639\u0638 \u0648\u0627\u0644\u0625\u0631\u0634\u0627\u062f\u060c \u0648\u0623\u0639\u062f \u0644\u0647 \u0627\u0644\u0639\u062f\u0629 \u0645\u0646 \u0639\u0644\u0648\u0645 \u0627\u0644\u0634\u0631\u064a\u0639\u0629 \u0648\u0627\u0644\u0644\u063a\u0629 \u0648\u0627\u0644\u0623\u062f\u0628 \u0648\u0627\u0644\u062a\u0627\u0631\u064a\u062e\u060c \u0641\u062d\u0641\u0638 \u0627\u0644\u0643\u062b\u064a\u0631 \u0645\u0646 \u0627\u0644\u0623\u062d\u0627\u062f\u064a\u062b \u0648\u0627\u0644\u0631\u0642\u0627\u0626\u0642 \u0648\u0627\u0644\u0623\u062e\u0628\u0627\u0631 \u0648\u0627\u0644\u062d\u0643\u0627\u064a\u0627\u062a \u0648\u0627\u0644\u0623\u0634\u0639\u0627\u0631\u060c \u0645\u0639 \u0625\u062d\u0627\u0637\u0629 \u062a\u0627\u0645\u0629 \u0628\u0623\u062d\u0648\u0627\u0644 \u0639\u0635\u0631\u0647 \u0648\u0634\u0624\u0648\u0646 \u0645\u062c\u062a\u0645\u0639\u0647\u060c \u0648\u0623\u062d\u0648\u0627\u0644 \u0627\u0644\u0646\u0627\u0633 \u062e\u0627\u0635\u062a\u0647\u0645 \u0648\u0639\u0627\u0645\u062a\u0647\u0645\u060c \u0648\u0639\u0646\u062f\u0645\u0627 \u0627\u0633\u062a\u0648\u062a \u0644\u0647 \u0623\u062f\u0648\u0627\u062a\u0647 -\u0648\u0647\u0648 \u0628\u0639\u062f \u0641\u064a \u0645\u0642\u062a\u0628\u0644 \u0627\u0644\u0639\u0645\u0631- \u0623\u0642\u0628\u0644 \u064a\u0639\u0642\u062f \u0645\u062c\u0627\u0644\u0633 \u0627\u0644\u0648\u0639\u0638\u060c \u0648\u0643\u0627\u0646 \u0623\u0648\u0644\u0647\u0627 \u0641\u064a \u062c\u0627\u0645\u0639 \u0627\u0644\u0645\u0646\u0635\u0648\u0631.","\u0648\u0628\u062f\u0623\u062a \u0645\u062c\u0627\u0644\u0633\u0647 \u062a\u0633\u062a\u0642\u0637\u0628 \u0627\u0644\u0646\u0627\u0633\u060c \u0641\u0627\u0632\u062f\u062d\u0645 \u0639\u0644\u064a\u0647 \u0623\u0647\u0644 \u0628\u063a\u062f\u0627\u062f\u060c \u064a\u0646\u0647\u0644\u0648\u0646 \u0645\u0646 \u0639\u0644\u0645\u0647 \u0648\u0648\u0639\u0638\u0647 \u0648\u062a\u0630\u0643\u064a\u0631\u0647 \u062e\u0627\u0635\u062a\u0647\u0645 \u0648\u0639\u0627\u0645\u062a\u0647\u0645\u060c \u062d\u062a\u0649 \u0635\u0627\u0631 \u0639\u0644\u0645\u064b\u0627 \u0645\u0646 \u0623\u0639\u0644\u0627\u0645 \u0628\u063a\u062f\u0627\u062f\u060c \u0648\u0645\u0641\u062e\u0631\u0629 \u062a\u0641\u0627\u062e\u0631 \u0628\u0647\u0627 \u063a\u064a\u0631\u0647\u0627 \u0645\u0646 \u0627\u0644\u0645\u062f\u0646\u060c \u0641\u0643\u0627\u0646 \u0632\u0648\u0627\u0631 \u0628\u063a\u062f\u0627\u062f \u064a\u062d\u0631\u0635\u0648\u0646 \u0639\u0644\u0649 \u062d\u0636\u0648\u0631 \u0645\u062c\u0627\u0644\u0633\u0647 \u0627\u0644\u062a\u064a \u0644\u0645 \u064a\u0643\u0646 \u0644\u0647\u0627 \u0646\u0638\u064a\u0631 \u0641\u064a \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a."],t.s)
