B.avk=s(["\u0643\u0627\u0646 \u0627\u0628\u0646 \u0627\u0644\u062c\u0648\u0632\u064a \u0623\u0646\u064a\u0642\u064b\u0627 \u0641\u064a \u0645\u0638\u0647\u0631\u0647 \u0646\u0632\u0647\u064b\u0627 \u0646\u0638\u064a\u0641\u064b\u0627\u060c \u0645\u062a\u0646\u0639\u0645\u064b\u0627 \u0641\u064a \u0645\u0639\u064a\u0634\u062a\u0647\u060c \u0643\u0645\u0627 \u0643\u0627\u0646 \u0631\u062d\u0645\u0647 \u0627\u0644\u0644\u0647 \u0645\u062a\u062d\u062f\u062b\u064b\u0627 \u0628\u0627\u0631\u0639\u064b\u0627\u060c \u0625\u0646 \u0623\u0631\u0627\u062f \u0623\u0646 \u064a\u0636\u062d\u0643 \u0623\u0636\u062d\u0643 \u0627\u0644\u062b\u0643\u0644\u0649 \u0628\u0645\u0627 \u064a\u0633\u0631\u062f \u0645\u0646 \u0623\u062e\u0628\u0627\u0631 \u0627\u0644\u0628\u062e\u0644\u0627\u0621 \u0648\u0627\u0644\u062d\u0645\u0642\u0649 \u0648\u0627\u0644\u0645\u063a\u0641\u0644\u064a\u0646 \u0648\u0627\u0644\u0645\u062a\u0645\u0627\u062c\u0646\u064a\u0646 \u0648\u0627\u0644\u0638\u0631\u0627\u0641.","\u0648\u0625\u0630\u0627 \u0623\u0631\u0627\u062f \u0623\u0646 \u064a\u0628\u0643\u064a \u0623\u0628\u0643\u0649 \u0627\u0644\u0635\u062e\u0631 \u0627\u0644\u0623\u0635\u0645 \u0628\u0645\u0627 \u064a\u0642\u0635 \u0645\u0646 \u0648\u0635\u0641 \u0627\u0644\u0622\u062e\u0631\u0629 \u0648\u0623\u0647\u0648\u0627\u0644 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0648\u0633\u064a\u0631 \u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646 \u0627\u0644\u0632\u0627\u0647\u062f\u064a\u0646\u060c \u0648\u062e\u0648\u0641\u0647\u0645 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0641\u0643\u0627\u0646 \u064a\u0645\u0632\u062c \u0628\u064a\u0646 \u0647\u0630\u0627 \u0648\u0630\u0627\u0643 \u0644\u064a\u062c\u0630\u0628 \u0627\u0644\u0642\u0644\u0648\u0628\u060c \u0648\u064a\u0631\u0648\u062d \u0639\u0646 \u0627\u0644\u0646\u0641\u0648\u0633 \u0644\u062a\u0633\u062a\u0639\u062f \u0644\u0633\u0645\u0627\u0639 \u0645\u0648\u0627\u0639\u0638\u0647\u060c \u0641\u0647\u0648 \u062e\u0628\u064a\u0631 \u0628\u0645\u0627 \u064a\u0635\u0644\u062d \u0627\u0644\u0646\u0641\u0648\u0633 \u0648\u064a\u062a\u0623\u0644\u0641\u0647\u0627.","\u0643\u0645\u0627 \u062a\u0645\u064a\u0632 \u0627\u0628\u0646 \u0627\u0644\u062c\u0648\u0632\u064a -\u0631\u062d\u0645\u0647 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649- \u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0641\u0635\u0627\u062d\u062a\u0647 \u0648\u063a\u0632\u0627\u0631\u0629 \u0645\u062d\u0641\u0648\u0638\u0647 \u0628\u0633\u0631\u0639\u0629 \u0627\u0644\u0628\u062f\u064a\u0647\u0629 \u0648\u0627\u0644\u062c\u0648\u0627\u0628 \u0627\u0644\u062d\u0627\u0636\u0631\u060c \u0648\u0642\u062f \u0630\u0643\u0631\u0648\u0627 \u0639\u0646\u0647 \u0642\u0635\u0635\u064b\u0627 \u0637\u0631\u064a\u0641\u0629\u060c \u0645\u0646\u0647\u0627: \u0623\u0646 \u0631\u062c\u0644\u064b\u0627 \u0633\u0623\u0644\u0647 \u0645\u0646 \u0623\u0641\u0636\u0644 \u0627\u0644\u0646\u0627\u0633 \u0628\u0639\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0643\u0627\u0646\u062a \u0627\u0644\u0623\u062c\u0648\u0627\u0621 \u0628\u064a\u0646 \u0627\u0644\u0634\u064a\u0639\u0629 \u0648\u0627\u0644\u0633\u0646\u0629 \u0645\u0634\u062d\u0648\u0646\u0629\u060c \u0641\u0642\u0627\u0644 \u0639\u0644\u0649 \u0627\u0644\u0628\u062f\u064a\u0647\u0629: \u0623\u0641\u0636\u0644 \u0627\u0644\u0646\u0627\u0633 \u0645\u0646 \u0643\u0627\u0646\u062a \u0628\u0646\u062a\u0647 \u062a\u062d\u062a\u0647\u060c \u0641\u0642\u0627\u0644 \u0623\u0647\u0644 \u0627\u0644\u0633\u0646\u0629: \u064a\u0642\u0635\u062f \u0623\u0628\u0627 \u0628\u0643\u0631\u061b \u0644\u0623\u0646 \u0627\u0628\u0646\u062a\u0647 \u0639\u0627\u0626\u0634\u0629 \u0643\u0627\u0646\u062a \u062a\u062d\u062a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0642\u0627\u0644\u062a \u0627\u0644\u0634\u064a\u0639\u0629: \u0628\u0644 \u064a\u0642\u0635\u062f \u0639\u0644\u064a\u064b\u0651\u0627\u061b \u0644\u0623\u0646 \u0628\u0646\u062a\u0647 \u0641\u0627\u0637\u0645\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 \u0643\u0627\u0646\u062a \u062a\u062d\u062a\u0647."],t.s)
